insert into public.theories (id, question_id, legacy_author_key, identity_mode, thesis, paragraphs, change_mind, status, dmz_pick, starter, needs_review, legacy_url, created_at, published_at) values
  ('l5740', 'if-you-could-start-a-country-from-scratch-what-would-it-be-like', 'steve-f', 'name', null, array['I’d design a 100% electronic democracy where every issue in front of the people would be voted on electronically via a website. Every citizen would be required by law to vote in national elections and the majority opinions would bind legislatures on the issues, including the national budget, tax code and foreign/trade policy. Every law proposed by any legislator would have to have buy-in or co-sponsorship for 10% of the voting public before it could be opened up for consideration in the house/parliament. This should eliminate the ability of small special interests to shove/lobby self-serving tax breaks thru congress. I would make the will of the people more important than vetoes, filibusters and bills with so many amendments they can’t be read by the congress or people before the vote. If any law is ruled unconstitutional by our Supreme Court, the legislators who sponsored the bill would be immediately expelled from office and forbidden to ever run again. All sessions and subcommittee meetings would be public, taped and archived forever. I would have web cams in the Presidents office and all top cabinet officials so their work and conversations are visible too.', 'There would be term limits, mandatory retirement ages, STRICT oversight for corruption and conflict of interest, and PUBLIC financing of elections and referendums. NO corporate paid gifts or speeches, NO legislators ever becoming lobbyists and MANDATORY media coverage of candidate debates where the questions come from the public, not pundits.', 'I would hope the citizens of this mythical country would want the government to work more like Norway and Denmark than the USA, with a progressive income tax, a very small “VAT” on liquor, pot and cigarettes, a strong social safety net, equal pay for equal work, universal healthcare and education, great investment in public transportation with a commitment to renewable energy and minimal international intervention.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/personal/personal-3-1-5/', '2020-05-29T12:00:00Z', '2020-05-29T12:00:00Z'),
  ('l5738', 'if-you-could-start-a-country-from-scratch-what-would-it-be-like', 'forrest-t', 'name', null, array['New Canada – It is a country that my friend and I have been creating over the past couple of years. Goverment – The Executive Branch consists of a Prime Co-Chancellor and a Sub Co-Chancellor, who are mostly all-powerful. The Legislative Branch consists of about 4 people, 2 of which are the current Co-Chancellors, they are mostly useless, only used by the Co-Chancellors, when they are in dispute. There is also a large legal codex, which I, as the Prime Co-Chancellor, cannot find for my Sub Co-Chancellor wrote it and subsequently hid it. The government is part of 706, Inc., which has many departments, such as DAS, the Department of Astronautical Services, and the DRD, the Department of Redundacy Department, etcetera. 706’s, and New Canada’s, main product/export is slightly irradiated chocolate milk, with convenient radiation kits in the cap. We have a colonized space station, and a colony on the moon, both of which are self-sustaining.', 'Tech', 'We have the most advanced tech on the planet including scifi-like shields and plasma guns, although we would have trouble winning a war due to the size of our armed forces being at most 5 people, although all are in power armor.', 'Land', 'We have the capital province of New Canada, and the provinces of New Quebec, and New New Canada.', 'Currency', 'Our main currency is the Shilling, which is worth millions of USD, due to the fact there are maybe 2o total coins.', 'The entire country is based off my Minecraft games with my friends.']::text[], null, 'live', true, false, false, 'https://quarxtheories.com/personal/personal-3-1-4/', '2020-05-29T12:00:00Z', '2020-05-29T12:00:00Z'),
  ('l5736', 'if-you-could-start-a-country-from-scratch-what-would-it-be-like', 'connor-a', 'name', null, array['I live in the United States of America. With that in mind, my ideas are directly influenced by America’s political system and the ways I see improvement in it, but also knowledge of other countries’ political systems that work well. I’ve had the blueprints in my head for some time but they have never been written down yet. There is certainly lots that I forgot along the way that didn’t make it to this point. With that in mind, here’s my ideal government:', '• Have a Swiss based direct democracy voting system: people can submit their own bills to the congressional body(whatever they call it) to be discussed and be voted on by citizens by referendum', '• A third, but smaller branch of congress made of short term appointed experts in various fields of knowledge that fact check, research any relevant information that would go into making a decision, and anything else that prevents emotional decisions(like declaring war on Iraq). These experts, like te religious law court in Saudi Arabia, can have conditional veto power on any ignorant decision; at least they can omit or revise ill-advised language in a bill before sending it back for reconsideration. Essentially this group would be like the crazy generic old scientist who was right all along in the movies telling the decision makers the best thing to do.', '• Preferential voting and proportional representation to have multiple parties emerge rather than just two dominant ones, which reduces polarization in politics.', '• Two Vice Presidents, not one. (American presidents usually have a vice pres on the other end of politics to “balance the ticket”. With three at the head of the presidency, there may be less deadlock.)', '• Constitutional review powers built into the constitution, because people complain about the Supreme Court making decisions they don’t like using the powers granted to them after the founding of the constitution. Also, there would be twelve of them, not nine, which would allow for the possibility of an even split so the decisions can be delayed or discussed more with more opinions involved.', '• Right to health and safety provided by the government.', '• Citizenship achieved after three years of living in a country. Citizenship also grants the ability to run for president. No worries about being a natural born citizen because it is not a constitutional requirement.', '• Federal supremacy. No more worrying about local laws. Laws are universal, and the only thing that varies locally is local taxes for local infrastructure maintenance. Subdivisions are mainly for administrative convenience. Llocal laws may exist, but only to fill in local variations that the federal law doesn’t account for however, federal law still can override these laws if they are contradictory. Also, every law enacted locally is not funded by federal money and it is up to to local administration to cover costs(so we don’t have one place feeding off the surpluses of the others.)', '• Wikipedia style law database curated by experts to keep laws up to date on any changes and bring old laws forward for possible revision. This is to help make sure no archaic/incompatible laws are being used in government actions to make sure that the government is as efficient and up to date as possible.', '• Presumed universal equality of opportunity by law, but allowing room for pluralistic accommodations that account for the individual differences that everyone has.', '• Government provides all essential services: electrical and water utilities, health services, etc. None of that free market stuff we rely on that costs more than what we could get with just centrally distribute it. Nit part of the constitution but is part of the institution.', 'Thats all I have right now. But essentially this is designed to have a smarter, more efficient, less gridlocked nation and by extension government as well.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/personal/if-you-could-start-a-country-from-scratch-what-would-it-be-like/', '2020-05-29T12:00:00Z', '2020-05-29T12:00:00Z'),
  ('l6239', 'if-you-could-start-a-country-from-scratch-what-would-it-be-like', 'deanna-a', 'name', null, array['I would like to start off this country with observing the land, it’s rhythms, cycles, seasons, patterns, weather, animals, plants, waters, etc. Each person would be encouraged to do so, to sit and observe, to see what they see. The country would run by a ‘take what you need’ vs masculine ‘take what you want’ idea. Children would not go to school to simply sit in classrooms all day long, they would be taught through ways of many different people, in different skillsets and application of creative thinking, they would connect with elders to learn how to sustain the land and the community that they live upon. I think it all starts with children, and so starting them off to trust their intuition, to teach them beyond sex, to care for the land and their bodies, to encourage them to develop uniquely would create a group of people who are self empowered and without every psychological ailment in the book. There are many more aspects to talk about, but this is the one I want to bring to the forefront for now.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/personal/if-you-could-start-a-country-from-scratch-what-would-it-be-like/if-you-could-start-a-country-from-scratch-what-would-it-be-like-2/', '2020-07-05T12:00:00Z', '2020-07-05T12:00:00Z'),
  ('l5913', 'what-is-the-greatest-teaching-the-covid19-pandemic-is-offering-humankind', 'the-kid', 'name', null, array['Listen to mama Earth! The Earth’s intelligence is far greater than ours – at least the level of intelligence we have been operating at collectively. Whether it is through rising seas, changing weather patterns, storm surges, respiratory infections, or another means, the Earth speaks through a feedback loop. She will always reflect back to us what we emanate, in just the same way as mass deforestation, fires, and pollution in the lungs of the Earth (the Amazon rainforest) quickly leads to a respiratory infection in the lungs of humankind. There is perhaps no greater mirror for our collective internal wellbeing than our own planet Earth.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/qotw-2/', '2020-06-01T12:00:00Z', '2020-06-01T12:00:00Z'),
  ('l5908', 'what-is-the-greatest-teaching-the-covid19-pandemic-is-offering-humankind', 'nick-s', 'name', null, array['Space is an ally. Space allows the planet to begin to heal. Space allows people to break cycles of habit and inertia. Space allows people to reflect, contemplate, and create in a way they otherwise would not. Space allows people to clean the slate – to find renewed gratitude for that which they began to take for granted. Space allows us to find each other in a new way, to re-define our relationships – with ourselves and each other.', 'Meher Baba, a great Indian yogi, once said, ‘The one creates the many in order to see itself, in order to know itself, in order to come back to itself.’ Similarly, a Zen master went off to discover the truth and came back with a phrase, ‘At first I saw mountains as mountains and rivers as rivers. Then, I saw mountains as NOT mountains and rivers as NOT rivers. Then, finally, I saw mountains as mountains and rivers as rivers again.’ In 1968, the Apollo 8 space mission turned the camera to see the Earth, capturing ‘earthscape’ – the first image of the Earth from space. All of these stories highlight a similar theme – that space allows us to see things for what they are in full. This is in contrast to the pixel-sized view we usually have of something that we are too close to.', 'The COVID19 pandemic is allowing us to take space in many ways, and it is a direct offering from the Earth to allow this space to bestow wisdom upon us. While it is quite uncertain whether we will allow this wisdom to penetrate us this round, I believe it will be the Earth’s method of teaching until we do.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/qotw0601/qotw0601-1/', '2020-06-01T12:00:00Z', '2020-06-01T12:00:00Z'),
  ('l5964', 'what-is-the-greatest-teaching-the-covid19-pandemic-is-offering-humankind', 'travis-h', 'name', null, array['Greatness of teaching is dependent on context. One: Unexamined group consciousness will emerge into external reality, eg. social distancing as continuation of social abstraction via tech. Two: We need to optimize our institutions and systems for anti-fragility. Currently we are efficient but fragile. Three, our collective sensemaking apparatus is broken on every level; data input, framing, interpretation, and decision making. Four, we may not want to optimize for prevention of death over everything else.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/what-is-the-greatest-teaching-the-covid19-pandemic-is-offering-us/', '2020-06-03T12:00:00Z', '2020-06-03T12:00:00Z'),
  ('l5960', 'what-is-the-greatest-teaching-the-covid19-pandemic-is-offering-humankind', 'ruby', 'name', null, array['The Covid-19 is teaching mankind that, surprise, we don’t have control, even though that is a very uncomfortable feeling for most people. Once that idea sinks in, then people recalibrate, and work within this new paradigm. And surprise, most people discover that control is a burden. So on a good day, Covid-19 is freeing us to face mortality, love each other more deeply, work for the greater good, be braver, and eat more of the canned food in our cupboards. On a bad day, it’s teaching us to watch out for ourselves, be afraid, be very afraid, hoard toilet paper, shutdown, and watch too much contradictory and polarizing news. 
Undeniably, Covid -19 has made earthlings slow down, and that is a good thing. And personally, it has made me more sensitive to the needs of people who feel alone. To connect me to the universal feelings of grief and fear, but also triumph and hope.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/what-is-the-greatest-teaching-the-covid19-pandemic-is-offering-humankind/', '2020-06-03T12:00:00Z', '2020-06-03T12:00:00Z'),
  ('l6085', 'what-is-the-greatest-teaching-the-covid19-pandemic-is-offering-humankind', 'mystic-quartz', 'name', null, array['I think the pandemic is showing us the fragility of our bodies and the fragility of our experience of life on Earth. It is teaching me impermanence and how you can never truly get used to a certain state of being on this planet because everything is changing all the time around us, by nature. I think it’s showing us that Gaia is angry and that we haven’t been treating her very well for too long. I think this really needed to happen to open all of our eyes wide enough to create real sustainable change.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/qotw0601/qotw0601-3/', '2020-06-20T12:00:00Z', '2020-06-20T12:00:00Z'),
  ('l6083', 'what-is-the-key-piece-in-the-success-of-any-movement', 'bill-k', 'name', null, array['In my opinion, historically the key to successful political movements has been either good timing or charismatic leadership. However, (while good timing and charisma are still potent) I believe that in the last couple of generations media control has emerged as the most significant key to success. And, looking to the future, it’s not hard to imagine that new forms of media and public communication technologies (Facebook, Twitter, cyberbots, etc.) will be invaluable manipulative tools for political success.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/qotw0621/qotw0621-1/', '2020-06-20T12:00:00Z', '2020-06-20T12:00:00Z'),
  ('l6080', 'what-is-the-key-piece-in-the-success-of-any-movement', 'greg-s', 'name', null, array['The declaration of surrender was touted as a triumph: “Microsoft Loves Linux,” the headline read, but just a decade earlier, the firm’s then CEO, Steve Ballmer, had called Linux a cancer. The all-powerful tech giant had lost and lost badly — to a ragtag band of revolutionaries, no less — but still seemed strangely upbeat.', 'Overthrows like these are becoming increasingly common and not just in business. As Moisés Naím observed in his book, The End of Power, institutions of all types, from corporations and governments to traditional churches, charities, and militaries, are being disrupted. “Power has become easier to get, but harder to use or keep,” he writes.', 'The truth is that it’s no longer enough to capture the trappings of power, because movements made up of small groups are able to synchronize their actions through networks. So if you want to effect lasting change today, it’s no longer enough to merely command resources, you have to inspire opponents to join your cause. History shows these movements follow a clear pattern.', 'Make Your Purpose Clear', 'In a previous article about why some movements succeed and others fail, I compared the Occupy and Otpor movements. Occupy, as most people are aware, was a band of young activists who took over Zuccotti Park in Manhattan to protest against social and economic inequality. Otpor was a similar group in Serbia that sought to overthrow the Milošević regime.', 'Despite their similarities, the results they achieved couldn’t have been more different. In the case of Occupy, the protesters were back home in a few short months, achieving little. Otpor, on the other hand, not only toppled Milošević, it went on to train activists in the Georgian Rose Revolution, the Ukrainian Orange Revolution and the April 6 Youth Movement in Egypt, just to name a few.', 'One reason for the disparity is that while Otpor had one clear goal, to overthrow Milošević, it was hard to tell what Occupy wanted to be done. As Joe Nocera noted in a New York Times column, the group “had plenty of grievances, aimed mainly at the “oppressive” power of corporations,” but “never got beyond their own slogans.”', 'Clarity of purpose is a common theme in successful movements. For example, Gandhi’s allies questioned his idea to make the salt tax a primary focus, because they favored a plan for more comprehensive change, but he saw that a single issue, even a small one, could unify the nation and break British Raj’s monopoly on power.', 'Values Are More Important Than Slogans', 'In Team of Teams, General Stanley McChrystal argued that building a shared purpose is essential to distributed action. “An organization should empower its people, but only after it has done the heavy lifting of creating shared consciousness,” he observed.', 'Here again, we see a stark contrast between Occupy and Otpor. While both took a non-hierarchical approach, distributing power broadly, Otpor was far more organized and disciplined, creating a training curriculum and holding bootcamps to indoctrinate new members in the principles of nonviolent struggle.', 'Like clarity of purpose, an emphasis on training is a common attribute of successful movements. In John Lewis’s memoir of his role in the civil rights movement, Walking With the Wind, he continually underlines the importance of training activists. Protests are incredibly stressful and often meet with fierce opposition. Training helps activists maintain discipline.', 'If you look at pictures or film of the sit-ins and marches of the 1960’s, you’ll see nicely dressed young men and women keeping their composure in the face of snarling dogs and police batons. That was a tactic civil rights protesters intentionally adopted, and it worked. Now compare that to the unkempt protesters at Occupy events. That’s the difference that creating and instilling values makes.', 'The Strength Of A Movement Is Not Large Crowds, But Small Groups', 'In the 1950’s, the prominent psychologist Solomon Asch undertook a pathbreaking series of conformity studies. What he found was that in small groups, people will conform to a majority opinion. More recent research suggests that the effect applies not only to people we know well, but that we are also influenced even by second and third degree relationships.', 'So while we usually notice successful movements after they have begun to attract large crowds and hold massive demonstrations, those are effects, not causes, of successful mobilization. It is when small groups connect — which has become exponentially easier in the digital age — that they gain their power.', 'In The Tea Party and the Remaking of Republican Conservatism, Theda Skocpol and Vanessa Williamson observed that the movement was largely based in a wide-ranging assortment of groups that met in local cafes and coffee shops. “There is not, therefore, a single Tea Party organization or even a well coordinated network,” they wrote.', 'That’s why founders of Otpor warn in their training manuals about the dangers of holding large demonstrations too early. Rather, they suggest that protesters focus on building capacity and strategically sequencing their actions to gain support. If you can do that successfully, eventually the large crowds will take care of themselves.', 'Overcome Increasing Thresholds Of Resistance', 'While focusing on building a shared purpose among a network of small groups is an effective way to build ideological continuity, it also presents a danger. Tight-knit groups of likeminded people often forget that many others do not hold the same views. Often, as in the case of the Bernie Bro phenomenon last summer, they come to regard dissent as illegitimate.', 'That’s a real problem, because for any movement to spread and effect change, it needs to overcome steadily increasing thresholds of resistance. If only the views held inside the movement are seen as legitimate, then outsiders come to be seen as targets for attack. That’s why so many movements never create change that lasts, they create enemies that undermine their cause.', 'Consider, on the other hand, Martin Luther King’s “I Have A Dream” speech. It spoke not just to the problems of African Americans, but to the founding principles of the nation. It was that approach that grew the movement beyond its core constituency of southern blacks and made inroads to the larger public.', 'The truth is that movements rarely, if ever create change themselves. Rather, they inspire change through influencing outsiders. Consider that in the end that it was President Lyndon Johnson, a southern white man from Texas, who signed the Civil Rights Act that Martin Luther King, Jr. had championed.', 'Rely on Engagement, Not on Rhetoric', 'Eight years ago, Barack Obama created a powerful movement that swept him to a stunning electoral victory, but inspired such fierce resistance that he had trouble enacting his agenda. Donald Trump now aims to lead a nation that seems, if possible, even more divided. We seem doomed to stay stuck in a cycle of recrimination.', 'While it is easy to place the blame for this polarization on the politicians themselves, we must also realize that they reflect the movements that brought them to power. All too often, we are content to live in different worlds and shout at our screens. And as long as some feel victimized and others feel demonized, we will remain a country divided.', 'You can write all the scathing tweets and heartfelt Facebook posts you want, but the truth is that rhetoric rarely persuades. The way to change minds is through face-to-face engagement. This is what President Obama was talking about when he said he won Iowa in 2008 because he “spent 87 days going to every small town, fair, fish fry, and VFW hall.” Similarly, progress on LGBT rights in America has not been made just because of eloquent arguments, but because of all the many personal interactions between straight Americans and their gay friends, neighbors, and colleagues.', 'We can only truly form a national consensus by internalizing the concerns of our fellow citizens and forming a common cause. If we can learn anything from successful movements throughout history, it’s this: lasting change does not come when one side delivers a knockout blow to the other, but when both sides are able to claim the victory as their own.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/qotw0621/qotw0621-2/', '2020-06-20T12:00:00Z', '2020-06-20T12:00:00Z'),
  ('l6183', 'what-can-we-learn-from-the-killing-of-george-floyd-and-the-protests-that-followe', 'peniel-j', 'name', null, array['As a 47-year-old African American, I received news of George Floyd’s tragic death as a painful reminder of my own personal vulnerability. When I was a black child growing up in New York City during the 1980s and 1990s, racial divisions were a prominent part of the social, political and cultural landscape that shaped my early life and my generation. We were told vivid stories by schoolteachers, via television documentaries and politicians of the way in which the civil rights movement transformed America by ending racial segregation, securing black voting rights and moving the nation closer to Dr. Martin Luther King Jr.’s vision of a ‘beloved community.’', 'My first encounter with the fear and loathing that black men could inspire in white people was both political and painful. In 1986, I started attending an overwhelming white high school in Queens. My freshman year was the first time a white person ever called me the N-word, a circumstance that ignited a melee and landed us both in the principal’s office.Michael Griffith, a black man chased to his death by a white mob in the Howard Beach section of Queens that same year, fared much worse than I did. Both events left me deeply troubled, but also politically exhilarated by the realization that the narrative of civil rights in America in history books differed greatly from my own experience.', 'Spike Lee’s film “Do The Right Thing” premiered the summer before I turned 17 and quickly became my own personal touchstone. My identification with the character Buggin’ Out’s efforts to boycott an Italian American-owned pizzeria for their failure to include pictures of black people on the restaurant’s wall of fame proved instructive. As did the movie’s heartbreaking depiction of the death of Radio Raheem from police violence. The movie’s coda, which drew quotes from Malcolm X preaching black dignity and Martin Luther King Jr. promoting black citizenship, remained stamped in my soul and is reflected in my work as a scholar to this day.', 'The precocious black boy who used the realization of personal vulnerability as inspiration to study broadly, empathize deeply and organize politically resides inside of me today, periodically brought to the fore by the latest example of a black man dying unjustly in America. George Floyd’s death is already affecting millions of precocious black boys and girls in America today, many of whom have taken to the streets to demonstrate both the values of their own lives and to honor those taken from us too soon.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/qotw0607/qotw0607-5/', '2020-06-24T12:00:00Z', '2020-06-24T12:00:00Z'),
  ('l6180', 'what-can-we-learn-from-the-killing-of-george-floyd-and-the-protests-that-followe', 'antoine-g', 'name', null, array['George Floyd. One in dozens of names that we know off the top of our heads, along with Ahmaud Arbery. Trayvon Martin. Sandra Bland. Philando Castille. Eric Garner. Tamir Rice. Laquan McDonald, Brionna Taylor. Racist actions resulting in the murders of Black people. Some by citizens, some by police. And countless others that have died at the hands of racism, whose names we forget. Why? Part of the reason is systemic racism in education. Seventhy-nine percent of educators are White. Yet 52 percent of our students identify as Black, Latinx, Asian/Pacific Islander, or Native American (National Center for Education Statistics).', 'So, what SHOULD we learn from George Floyd’s murder?', 'First, we must learn how to be anti-racist, not NOT racist. Dr. Ibram X. Kendi (author of How to Be an Antiracist) says, “I define an antiracist as someone who is expressing an antiracist idea or supporting an antiracist policy with their actions, and I define an antiracist idea as any idea that says the racial groups are equal.” To be anti-racist, we should learn about bias and do the lifelong internal work of uncovering, naming, sitting with, and talking about our biases. We ALL have biases. They’re part of our socialized brains. I have uncovered many of mine (and have many more) that have changed the way I interact with my Black students and students of color. The internal work is messy. It’s hard. You’ll get defensive. But keep asking yourself, “What will happen to my Black students if I don’t advocate for them?” DiAngelo’s White Fragility is PERFECT for this work.', 'Most important of all, we need to LISTEN to the Black community. We need to pull back the curtain on micro (and not-so-micro) aggressions toward students of color. There are infinite resources that will allow you to listen to the Black community and begin to understand why “reverse racism” and “all lives matter” are not things. Some are listed here, with the knowledge that my anti-racist journey is built on the shoulders of GIANTS, to whom I am immensely grateful.', 'Books I’ve used on anti-racism for teachers and students:', '• How to Be an Antiracist by Dr. Ibram Kendi', '• White Rage by Carol Anderson', '• Dying of Whiteness by Jonathan Metzl', '• Stamped by Kendi & Jason Reynolds (great for the younger set if you’re looking to do this work with your children at home or your middle or high school students)', '• This Book is Antiracist by Tiffany Jewell (great for middle grades and up in classrooms and at home)', '• We Got This: Equity, Access, and the Quest to Be Who Our Students Need Us to Be by Cornelius Minor', '• Being the Change: Lessons and Strategies to Teach Social Comprehension by Sara K. Ahmed. I use this as the base of my teaching bias and discrimination with my students.', '• An Indigenous People’s History of the United States for Young People, adapted by Jean Mendoza and Dr. Debbie Reese. This is the student version of the original written by Roxanne Dunbar-Ortiz and is a vital component of my social studies curriculum.', 'Finally, we must learn to teach this relevant and current topic to our students, no matter our discomfort. Our discomfort doesn’t matter. Again, sit with it. Say you are uncomfortable. Say you are new at being anti-racist. It’s OK to be vulnerable with students as you grapple with this work together.', 'This lifelong work: Uncovering our biases, listening, and teaching anti-racism is the work of teachers, and it is past time that we act on behalf of our kids.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/qotw0607/qotw0607-4/', '2020-06-24T12:00:00Z', '2020-06-24T12:00:00Z'),
  ('l6176', 'what-can-we-learn-from-the-killing-of-george-floyd-and-the-protests-that-followe', 'lorie-b', 'name', null, array['It is not enough to not be racist, we must be anti-racist. Many individuals, whether they are teachers, administrators, or teacher aides point to their own efforts working with minority communities and ask themselves what can I do to be part of the solution for their students. There are many things that can be done, from valuing diversity in the workforce, particularly in leadership, to teachers actually living in the community in which they teach. However, the greatest catalyst for change is to realize that we as individuals make up the system.', 'Teachers, coaches, support staff are the educational system. Each individual might not have personal animus toward any race, but that’s not enough. Neutrality is what gives us the system we have today. Silence in the face of systemic racism and oppression is no different from the police officers who stood idly by while Mr. Floyd pleaded for his life. We must be anti-racist, we must confront, name, and actively dismantle a system that benefits some but marginalizes others. That means we don’t teach history as a dry collection of facts but as a living, moving, drama that affects our students today. That means we select a curriculum that is not only from diverse editors but also raises issues of oppression. It means schools try to intervene when a student is chronically absent or in the behavior office regularly. It means we actively talk about race and racism in faculty meetings and department meetings instead of assuming “colorblindness.”', 'Unfortunately, the story of George Floyd is an all too familiar one. We have seen this story before; the protests eventually fade, the crowds will soon disperse until the next victim. Let’s hope that the legacy of Mr. Floyd this time is to do what we can as individuals to right the wrongs that we see everyday and be the voice to so many students who are voiceless.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/qotw0607/qotw0607-3/', '2020-06-24T12:00:00Z', '2020-06-24T12:00:00Z'),
  ('l6172', 'what-can-we-learn-from-the-killing-of-george-floyd-and-the-protests-that-followe', 'n-bailey', 'name', null, array['Systemic racism is not unique to the criminal justice system. It is far too easy to point out the martyrs of police killings: Eric Garner, Tamir Rice, Walter Scott, Alton Sterling, and Freddie Gray just to name a few. It is also easy to point out the racial disparities in incarceration rates, bail determinations by judges, and felony disenfranchisement to see that the criminal-justice system works differently for different races. Many have pointed out that the criminal-justice system isn’t dysfunctional at all but does exactly what it was designed to do.', 'After the bloody Civil War and the end of slavery, the 13th Amendment freed the slaves but offered the caveat of “involuntary servitude” for duly convicted criminals; shortly thereafter, black men began to be incarcerated at alarming rates for minor offenses such as loitering. The “War on Drugs” which succeeded the “Law and Order” platforms of the ’70s began the age of mass incarceration where millions of black and brown people were imprisoned and millions more were relegated to second-class citizens for being a felon.', 'Many would argue that the criminal-justice system offers a window into the American psyche, and what it reveals is a criminalization and fear of black and brown people and a dehumanization of said people.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/qotw0607/qotw0607-2/', '2020-06-24T12:00:00Z', '2020-06-24T12:00:00Z'),
  ('l6221', 'what-is-the-single-most-effective-way-to-make-a-positive-impact-on-a-daily-basis', 'nick-s', 'name', null, array['On what surprised him most about humanity:', '“Man surprised me most about humanity. Because he sacrifices his health in order to make money. Then he sacrifices money to recuperate his health. And then he is so anxious about the future that he does not enjoy the present; the result being that he does not live in the present or the future; he lives as if he is never going to die, and then dies having never really lived.”', '-H.H. The 14th Dalai Lama', 'We exist in a very complicated and vastly interconnected world — one in which our personal choices have immense implications within and beyond ourselves. However, within this web of constant contradiction and confusion, there are ways to live that induce positive effects on ourselves and others. The most significant, customizable mixture is between diet and waste. By committing to a new paradigm of a whole foods, vegetarian diet, and a compost- and recycle-heavy waste system, we are establishing a sustainable, personally and societally-beneficial system with profound short and long term implications. Here is how I see it…', 'Whole Foods, Local, Vegetarian/Vegan Diet', 'I will begin by pointing out how firmly immersed we are in modern society. The simple experience of going to a supermarket — being surrounded by package upon package, exotic fruits from across the world, conglomerated items of 50 illegible ingredients, etc — it has all become so normal to us that we hardly question it. These “supermarkets” are a new invention — within the last century in the West and still not a reality for much of the world today! We are still adapting to this new reality, but ironically, we are trashing our bodies in the process. For all but the entirety of human existence, we have eaten locally, we have eaten wholly, and we have had gratitude and connection to the food we consumed. Our health and balance as humans has been interfered with by our massive cerebrums, somehow convincing us that our own health is secondary to efficiency, temporal pleasure, and convenience. I invite you to re-connect with your human incarnation; to eat locally, to eat whole foods, and to cultivate gratitude for the life-giving nutrients of the food you are eating.', 'The most common hindrances to making this type of commitment are that (1) Time — People don’t have the time to cook for themselves. (2) Taste — We are so used to our sugary, salty, and processed foods that we are bound to suffer from withdrawal early. And (3) Money — So many people that eat unhealthy food do so simply because of the cost-effectiveness. These are all valid concerns, but there are counter-points to each.', '• Time – With one 20-minute shop once a week, we can pick up food for the entire week. With 20 or less minutes of cooking, we can cook enough food for two or more meals.', '• Taste – The ‘tasty but terrible for your health’ food is unnecessary. Fresh, clean food is pleasant for the taste buds and the body. Adopting a model of living where eating is not merely to please the palette but to maximize your body’s health opens up so many doors.', '• Money – An intelligent diet is a monetary investment. Supporting the local Farmers Market is not only beneficial for the community and your health, it is affordable for your wallet. What runs up large tabs is un-thoughtful spending more than anything. Even if it is slightly more expensive to buy local, whole foods, the investment is a healthier you, a healthier community, and a healthier global economy. Of all of the things we spend money on, perhaps there is none more important than the food we put in our bodies.', 'See also:', '• Whole Food Diet On a Budget.', 'Zero/Low Waste Lifestyle', 'If you were to look in your garbage can, I infer that almost everything in it could have been diverted or avoided altogether. The vast majority of our garbage is either food waste, plastic, or other recyclable material. The elimination of waste is do-able with the intention and willingness to do so. It becomes especially do-able when we are living a lifestyle that promotes reduction in consumption, reuse of resources, and recycling/composting of the waste we do produce.', 'The Cycle — Most of our waste is dictated by our purchasing habits. Naturally, when we buy un-packaged food, we are drastically minimizing our first- and second-hand impact on the environment. By buying locally produced food, we are also bypassing the need to ship food long distances. Add in the abstinence from meat products, and we are drastically minimizing our second-hand footprint. Overall, by making these simple choices on a level of personal consumption, we are having immensely positive effects on the environment and the local and global market. Naturally, we will produce much less waste, much of which, when composted, becomes fertile soil for the next generation of crops.', 'Zero Waste Tips:', '• Create a compost bin and recycling bin: You could use a compostable bag that you keep in the freezer for your compost bin, and a normal garbage can for your recycling bin. Perhaps keep a small bin for the landfill, as you will find that there is very little in the way of “trash.”', '• Grow a garden: If you have the space, why not plant a garden? Enjoy fresh crops, a place to use your compost, and a project to re-connect you to nature, food, and your innate human qualities.', '• Check out: How To Compost', '3. Other steps: Avoid plastic, but re-use if necessary. Buy second-hand, sell old clothing. Donate old electronics. Take public transportation, fly less on airplanes. Invest in alternative energy, don’t support oil industry. Don’t pay for bottled water! Many more!', '• Check out: Ways to Reduce Your Carbon Footprint', '4. Reach out to your local government about implementing a municipal composting and single-stream recycling system. See where they’re at on these issues and whether they would consider investing in an overall cheaper, healthier, and all-around smarter alternative.', 'In a nutshell…', 'Implications Bedford, NY', 'Coming from an era of efficiency and entering an era of sustainability, we are going to have to adapt to a system that makes room for both. As citizens of this increasingly interconnected planet, we have to acknowledge that our actions have effects on others. As citizens of the US, more specifically, it becomes even more important that we choose lifestyles that place personal, communal, and global well-being over profit and temporal pleasure. As we shift our lifestyles to a more holistic paradigm, we are beginning to do the work necessary to sustain ourselves, the species and the planet.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/what-is-the-single-most-effective-way-to-make-a-positive-impact-on-a-daily-basis/qotw0628/', '2020-06-25T12:00:00Z', '2020-06-25T12:00:00Z'),
  ('l6219', 'what-is-the-single-most-effective-way-to-make-a-positive-impact-on-a-daily-basis', 'the-kid', 'name', null, array['Existing through a lens of ‘openness’. This means an openness to others’ ideas, beliefs and interests as well as to the mysteries constantly unfolding around us. This is the ground from which all positive impact arises. Most of the time, we exist in a closed off, conditioned world. To flick the switch inside our minds and choose to spend our precious conscious moments receptively opens the world up to be explored. Not only does this open our world up, but this way of existing is highly contagious, and offers the gift of curiosity and openness to all who we come into contact with.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/what-is-the-single-most-effective-way-to-make-a-positive-impact-on-a-daily-basis/what-is-the-single-most-effective-way-to-make-a-positive-impact-on-a-daily-basis-2/', '2020-06-25T12:00:00Z', '2020-06-25T12:00:00Z'),
  ('l6217', 'what-is-the-single-most-effective-way-to-make-a-positive-impact-on-a-daily-basis', 'kai-b', 'name', null, array['Existing in a joyous state of acceptance and appreciation for what is. Allowing what is, to be. Moving through the world in a state of joy. This means that we are not resisting or perpetuating existing challenges, but rather healing them through our awareness and presence. Then we can offer our appreciation (of what is), which can only help improve the moment for all life. So to summarize: moving through a world with a foundation of mindfulness and appreciation is the most sure and effective way to make a positive impact on a daily basis. To me, this is love. Present moment appreciation is love.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/uncategorized/what-is-the-single-most-effective-way-to-make-a-positive-impact-on-a-daily-basis/', '2020-06-25T12:00:00Z', '2020-06-25T12:00:00Z'),
  ('l6268', 'what-is-patriotism', 'awdhesh-s', 'name', null, array['We take patriotism to mean love of nation and the loyalty that follows. My country right or wrong. Even as an abstract idea, it is hard to see how thinking people justify blind loyalty. And considered historically, patriotism is plainly dangerous, helping to unleash military rampages in the name of nation and obliterating the essential democratic capacity to assess concrete and particular interests.', 'The ubiquitous loyalty to nation-state is puzzling. How is it that people become passionately devoted to the abstraction of the state and its symbols? Propaganda could not be the human condition, such as the attachments most feel for kin and community. And perhaps nationalistic propaganda acquires the force it does because it draws on these axiomatic attachments.', 'Still, there is a difference. However parochial the ties that bind people to clan or place, these ties have something to do with the concrete experience of people, so that threats to clan or place can sometimes be assessed by direct experience. Not so with flag and nation. When state leaders appeal to patriotism, they mobilize citizens by invoking foreign threats that cannot be assessed by ordinary people, except sometimes when it is too late, as in the aftermath of war. In the process, not only are people made to sacrifice lives and resources to the contests of state-makers but the emotions generated overwhelm popular capacities for a reasoned and conflictual domestic politics. Never has that been more obvious.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/what-is-patriotism/0705-3/', '2020-07-06T12:00:00Z', '2020-07-06T12:00:00Z'),
  ('l6266', 'what-is-patriotism', 'james-h', 'name', null, array['Nietzsche wrote that words with a history cannot be defined. Their meanings are in their stories, their biographies. That is surely the case with “patriotism.” Patriotism is as patriots have done. And in relatively recent times–say, since the American and French revolutions–those who have called themselves patriots or who have called others to the banner of patriotism have largely fallen into two camps.', 'The first company, whose signature is on so many of the bloodiest pages of the modern age, has its spiritual roots in the radical ideologies of the French Revolution. They announced the advent of a new god on earth and a new prophet/commander whose voice was the voice of that god. The new god, of course, was la patrie, the nation, and the new commander was the state.', 'Abbé Sieyès named the new god: “The nation exists before all. It is the origin of everything. It is the law itself.” By 1792, in a petition addressed to the National Assembly, the ferociously jealous claims of the of the new god were made chillingly clear: “The image of the patrie is the sole divinity which it is permitted to worship.”', 'Those claims have echoed in a thousand variations from that day to this. It is the worship of national power, of national greatness, nearly always expressed as power over other peoples and qualities, and as power that acknowledges no limits on its own assertion. This voice has been as clamorous and continuous in our own country as in many others. The line from Col. Alexander Hamilton to Lieut. Col. Oliver North is strong and pure.', 'The other company of patriots does not march to military time. It prefers the gentle strains of “America the Beautiful” to the strident cadences of “Hail to the Chief” and “The Stars and Stripes Forever.” This patriotism is rooted in the love of one’s own land and people, love too of the best ideals of one’s own culture and tradition. This company of patriots finds no glory in puffing their country up by pulling others’ down. This patriotism is profoundly municipal, even domestic. Its pleasures are quiet, its services steady and unpretentious.', 'This patriotism too has deep roots and long continuity in our history. Its voice is often temporarily shouted down by the battle cries of the first company, but it has never been stilled. Jefferson spoke for it, as did Lincoln and Martin Luther King Jr.', 'We should not be surprised if this voice is often heard lamenting or rebuking the country’s failures to live up to its own best ideals, which have always been the ideals of the fullest possible freedom and the most nearly equal justice for all. Its specifically political ideal found its finest expression in Lincoln’s “government of, by and for the people,” and the American domestic patriot is often heard calling fellow citizens and their officials to this standard. That call is distinctly a citizenly call, and never more so than when, as Father Mapple’s wonderful sermon in Moby-Dick has it, the citizen stands firm “against the proud gods and commodores of this earth” and calls every violation of the covenant to account “though he pluck it out from under the robes of Senators and Judges.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/what-is-patriotism/0705-2/', '2020-07-06T12:00:00Z', '2020-07-06T12:00:00Z'),
  ('l6263', 'what-is-patriotism', 'forrest-t', 'name', null, array['Patriotism is supporting your country all the time, and your government when it deserves it. Patriotism is the feeling of love and respect for your country, its history and traditions. Patriotism is a natural and probably the most important factor of the country’s success, because if people are the patriots, they work hard for the development of their country, protection of its historical heritage and improvement of the love towards the culture of the nation. The people who do not love their native country and have no idea about its traditions and history are not able to be called the people of this country, they are the simple citizens, who just live in its territory.', 'Patriotism is the major factor which makes people create human history, work hard, fight and die for their country. Without this factor there would be no wars, dignity and courage. When the aggressor tries to invade the country, it can simply capitulate, but it does not because there are people who want to see their country independent, flourishing and rich. No one enjoys when the stranger comes into his house and starts to set his own rules. The same thing is the country. If the invader starts to dictate with will, people start to protect their homes and the whole country with the purpose to maintain its identity and uniqueness.', 'Patriotism is the respect of the native history. It is natural and essential to be aware about the most important facts of the history of your country, because we learn many new and fascinating facts about the average people, their lifestyle, the failure and success and we start to realize how much does it cost to make the country prosperous, stable and convenient for life. Patriotism is not the love towards the territory of the country, it is the love towards the traditions and people who live on this territory, so it is important to have patriotic feeling in order to show the respect towards the ones who have contributed into the development of the country and its current peaceful condition.', 'It is a positive thing that patriotism is propagated since childhood, because children are the future of every country and if they love their country, they will strive to improve it further. Patriotism is not the humiliation of other countries and ethnicities; it is a natural love and respect towards the native country and this attitude should exist in everyone if he wants his country to be prosperous and esteemed.', 'Patriotism is when love of your own people comes first; nationalism, when hate for people other than your own comes first.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/what-is-patriotism/0705-1/', '2020-07-06T12:00:00Z', '2020-07-06T12:00:00Z'),
  ('l6294', 'can-one-ever-overcome-trauma', 'rachel-b', 'name', null, array['It depends on so many different factors. The type of trauma. What parts of your life it affected. What parts of your emotions it affected. Your coping mechanisms. How much you hide it from other people. How much you talk it out. How much you let other people help to ground you when your emotions from that time separate you from the current now. How much you accept your reactions as valid and try to work through them.', 'I am by far not an expert. I know my own experience only. Mine was PTSD from emotional relationship trauma x2. It took a few years and a couple psychologists and my now-husband to work through it. He’d say something in the same tone of voice as one of the previous two guys, and it would fly me back to that time. I’d flash back and mix up who he was and curl up in a ball. It was horrible. But whenever it would happen, I’d talk about it. I needed that external grounding. That reminder that my flight or fight response was no longer necessary because it was in the past, not now. I had to repeat that over and over. It became soothing – “that was 5 years ago, not now, not now, not now. This is a different house with a different person and different job and different life. And I don’t need to be that scared girl any more, because I’m safe.” Over time, the memories started to fade, and so did the reactions. Sometimes, they still come back. But the grounding is easier. It’s almost easier to believe it wasn’t real, because there’s nothing but pain there. I worked through the emotions and pain till I could safely put them in a box and forget. Pretty sure that if I saw either of the guys again, that box would open for a while. But I’d talk it out, find my grounding, and put it away again.', 'Again, that doesn’t work for everyone, it’s just one data point. But for me, that trauma was real and palpable. Now it’s a faded memory. So I’m going to call it possible.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/can-one-ever-overcome-trauma/qotw0712/', '2020-07-14T12:00:00Z', '2020-07-14T12:00:00Z'),
  ('l6316', 'can-one-ever-overcome-trauma', 'gail-b', 'name', null, array['Yes, talking therapies that focus on processing previous traumatic experience can help to process it. Examples of trauma processing therapies are as follows.', 'EMDR-Eye Movement Desensitization & Reprocessing-in this therapy the therapist reviews with you your recollection of the traumatic event. When eye movements are initiated, the therapist asks you to think of this narrative and also reflect on your emotion, sense of self statements and visceral feelings that you had in response to a traumatic frame. The eye movements help to draw (in an accelerated manner) all of those experiences to facilitate memory consolidation (especially into anterior regions of the prefrontal cortex).', 'Hypnotherapy Age Regression-the hypnotherapist asks you (while you are in the hypnotic state) to go back into time and to identify the time of the trauma. While in the hypnotic state the trauma memory is easily elicited along with associated sense of self statements and emotions. The hypnotherapist would need to develop a suggestion to share this elicited trauma memory with all of its disturbing emotion and senses of self with the awakening state. This can be troubling and overwhelming to the person if it is not done in increments.', 'Prolonged Exposure-the therapist and patient review the traumatic experience and then consciously examine different aspects of the traumatic experience over and over again until the person is desensitized to sensory aspects of the trauma.', 'Redecision Therapy-the therapist uses the current implicit metaphor of the trauma and then uses conscious age regression to go back into the time when the traumatic relationship or event had been experienced. Accessing the metaphor helps to elicit the emotion that had been associated with the trauma and to develop the trauma narrative.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/can-one-ever-overcome-trauma/qotw0712-3/', '2020-07-15T12:00:00Z', '2020-07-15T12:00:00Z'),
  ('l6313', 'can-one-ever-overcome-trauma', 'michael-f', 'name', null, array['A person never gets over a severe trauma. Trauma is branded in your brain like a bull is branded by a rancher. I spend more time thinking about the past traumas in my life than I do thinking about all the happy moments. I have several happy memories. Time doesn’t heal all wounds. You must ask a therapist about Cognitive Behavioral Therapy. I’ve had many kinds of therapy. CBT is the ONLY therapy which forced me to face my traumas. I was forced to ask: was this trauma my fault? I told my traumas I was letting them go. I own my past but I don’t have to let it control me this moment. I know what happened but I live this moment. I don’t live in the past and I’m not promised I’ll HAVE a tomorrow. You never get over a severe trauma. You can learn how to laugh and experience joy. I offer myself as evidence.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/can-one-ever-overcome-trauma/can-we-ever-overcome-trauma/', '2020-07-15T12:00:00Z', '2020-07-15T12:00:00Z'),
  ('l6309', 'can-one-ever-overcome-trauma', 'suzanna-a', 'name', null, array['As a result of working through my own complex trauma, I don’t believe we ever “overcome” trauma. There are many different types and causes of trauma. My psychology prof taught us that everyone is traumatised, because being born is traumatising. But here’s what my personal experience has taught me. I believe we make friends with it. Fist by recognising the pain it caused, then by grieving for what we “lost” as a result (in my case it was my innocence, trust and childhood).', 'And when we can look back at part of the experience without flashbacks or that gut-wrenching sting, we are lucid enough to start doing the cognitive work that will allow us to understand what we have gained as a result. We can appreciate how it has allowed us to experience things that have given us a wisdom beyond out years, for example, or an understanding of some aspect of human behaviour that those around us struggle with.', 'We can reach the stage where we are grateful for the trauma. We wouldn’t want anyone else to experience it, but we are glad that we did because we know how much it has enriched us!', 'And every time we get to this stage of acceptance with some aspect of our trauma, the decisions we make are determined less and less by our trauma, and more and more on the strengths our trauma helped us develop! And that’s a truly great place to be.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/can-one-ever-overcome-trauma/qotw0712-2/', '2020-07-15T12:00:00Z', '2020-07-15T12:00:00Z'),
  ('l6328', 'is-the-usa-the-greatest-country-in-the-world', 'joe-b', 'name', null, array['We rank 27th in the world in childhood education and last in the world for pre-school education. We also rank 27th in the world in healthcare and lack of access to it. We spend more per person on healthcare than any other industrialized country on earth and still millions do not have access to affordable healthcare.', 'We have the most expensive and lowest quality daycare/pre-school system in the world.', 'Americans can pay up to 67 more times for a drug than the next closest country. On average America pays four times more for prescription drugs than the rest of the world. Over the last eight years the combined profit of pharmaceutical companies was $744 billion.', 'So what makes America the greatest country on earth? Freedom? There are 100 countries in the world who have freedom.', 'The simple, honest answer to the question of whether America is the greatest country on earth is no.', 'That doesn’t mean we can’t once again become the greatest country on earth. We must take on the greed of the elites that run this country. We must remove the billionaires and their money from our political system.', 'We must move to a not-for-profit healthcare system where heath care is a fundamental human right.', 'There is a true class war brewing in this country that we must address before it spills into the streets.', 'On one end there is a movement behind Bernie Sanders and on the other is what got Donald Trump elected. The common denominator is that people are fed up with the establishment choking us in the name of greed. I hope we can make the transformational reform needed to give the treasure of this nation back to the people where it belongs.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/is-the-usa-the-greatest-country-in-the-world/qotw0719-3/', '2020-07-17T12:00:00Z', '2020-07-17T12:00:00Z'),
  ('l6325', 'is-the-usa-the-greatest-country-in-the-world', 'the-kid', 'name', null, array['This question alone is a very ‘American’ question and game to play. Yes, China, Russia, India… all these countries are also playing a similar game, but it is one we have started. Though a young country, we set the precedent for most of the rest of the world. The more we play a game of ‘America first’ and ‘we’re the best’, the more other countries play similar games. Imagine if we asked a different question instead. Something like, ‘Is the USA the country doing the most for the planet?’ This question inspires altruistic, connective, futuristic, and contemplative thought. This question re-directs the game and rating system towards our highest potential, sparking growth and maturity as a nation and as a species. Until then, we will continue playing a game of scarcity and hyper-competitiveness, decimating the earth, our relationships, our own internal wellbeing, and that of future generations.', 'I have long felt that the best thing that could happen to the US is that another country would take over as ‘greatest’. While this would be a right hook to the jaw of the American ego, it would end up forcing us to reflect, contemplate, and ultimately re-define many of our out-dated models. We would be like a CEO who goes through a mid-life crisis, ultimately emerging a new person, quitting his job, and starting an NGO instead. Our attachment to being the greatest country is one of the strongest hindrances to our actually being great. It is a palpable sense of constriction – the antithesis of freedom.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/is-the-usa-the-greatest-country-in-the-world/qotw0719-2/', '2020-07-17T12:00:00Z', '2020-07-17T12:00:00Z'),
  ('l6322', 'is-the-usa-the-greatest-country-in-the-world', 'gaia', 'name', null, array['The notion of the US being the greatest country in the world has become a centerpiece in the curriculum of all ‘Americans’. Whether it is through school – the pledge of allegiance, the study of US and world history, the choice of mandatory reading material, etc. Or whether it is through the media – intentionally censoring and prioritizing certain stories over others… Or whether it is through politics – the ‘right’ interweaving its identity with true ‘patriotism’. Patriotism and a sense of subtle superiority is engrained in the blood of anyone socialized in this country. It has been for as long as our nation has existed – and even longer, in fact.', 'Take this a step further and see that the vision of our founding fathers, of manifest destiny, of even the European colonization of this land at all, was born out of a sense of white superiority. A disease of egocentrism born out of a disconnection from other life forms and nature. As far back as one can trace, this sense of ‘whiteness’ has been the oppressive force in almost all major conflict through history.', 'It is hubris to call ourselves the greatest country in the world, having not yet repaid Native Americans for stealing their land, black folks for enslaving them, various countries for manipulating them, zapping their resources, and enslaving them in debt, women for devaluing their existence, other life forms for our manipulation of the environment, and future generations for the harm we are continuing to cause each day. Until we pay reparations for these atrocities, our work will not be done, and we will have no business calling ourselves the greatest country in the world.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/is-the-usa-the-greatest-country-in-the-world/qotw0719/', '2020-07-17T12:00:00Z', '2020-07-17T12:00:00Z'),
  ('l6360', 'if-the-human-species-were-to-near-extinction-would-we-join-together-or-fight-aga', 'arkady-m', 'name', null, array['In November 2018, the largest and most deadly wildfire in California history destroyed entire towns and displaced thousands of people. In 2017, Hurricane Harvey drowned southeast Texas under punishing, endless rain. And in early 2020, Australia continues to grapple with bushfires that threatened to engulf the continent over its summer. Apocalyptic-scale disasters happen every day (and more often now, as climate change intensifies weather patterns all over the world.) Apocalyptic disaster isn’t always the weather, either: it’s human-made, by war or by industrial accident; by system failure or simple individual error. Or it’s biological: the flu of 1918, the Ebola outbreaks in 2014, COVID-19 now.', 'In science fiction, apocalypse and what comes after is an enduring theme. Whether it’s pandemic (like in Emily St. John Mandel’s Station Eleven and Stephen King’s The Stand), nuclear (such as Theodore Sturgeon’s short story “Thunder and Roses” or the 1984 BBC drama Threads), or environmental (Octavia Butler’s Parable of the Sower, Kim Stanley Robinson’s New York 2140, and a slew of brilliant short fiction, including Tobias Buckell’s “A World to Die For” (Clarkesworld 2018) and Nnedi Okorafor’s “Spider the Artist” (Lightspeed 2011), disaster, apocalypse, and destruction fascinate the genre. If science fiction is, as sometimes described, a literature of ideas, then apocalyptic science fiction is the literature of how ideas go wrong—an exploration of all of our bad possible futures, and what might happen after.', 'Most of apocalyptic literature focuses on all the terrible ways that society goes wrong after a society-disrupting disaster, though. This is especially prevalent in television and film—think of The Walking Dead or 28 Days Later where, while the zombies might be the initial threat, most of the horrible violence is done by surviving humans to one another. This kind of focus on antisocial behavior—in fact, the belief that after a disaster humans will revert to some sort of ‘base state of nature’—reflects very common myths that exist throughout Western culture. We think that disaster situations cause panic, looting, assaults, the breakdown of social structures—and we make policy decisions based on that belief, assuming that crime rises during a crisis and that anti-crime enforcement is needed along with humanitarian aid.', 'But absolutely none of this is true.', 'The myth that panic, looting, and antisocial behavior increases during the apocalypse (or apocalyptic-like scenarios) is in fact a myth—and has been solidly disproved by multiple scientific studies. The National Earthquake Hazards Reduction Program, a research group within the United States Federal Emergency Management Administration (FEMA), has produced research that shows over and over again that “disaster victims are assisted first by others in the immediate vicinity and surrounding area and only later by official public safety personnel […] The spontaneous provision of assistance is facilitated by the fact that when crises occur, they take place in the context of ongoing community life and daily routines—that is, they affect not isolated individuals but rather people who are embedded in networks of social relationships.” (Facing Hazards and Disasters: Understanding Human Dimensions, National Academy of Sciences, 2006). Humans do not, under the pressure of an emergency, socially collapse. Rather, they seem to display higher levels of social cohesion, despite what media or government agents might expect…or portray on TV. Humans, after the apocalypse, band together in collectives to help one another—and they do this spontaneously. Disaster response workers call it ‘spontaneous prosocial helping behavior’, and it saves lives.', 'Spontaneous mobilization to help during and immediately after an apocalyptic shock has a lot of forms. Sometimes it’s community-sourced rescue missions, like the volunteer boat rescue group who call themselves the Cajun Navy. During Hurricane Harvey, the Cajun Navy—plus a lot of volunteer dispatchers, some thousands of miles away from the hurricane—used the walkie-talkie app Zello to crowdsource locations of people trapped by rising water and send rescuers to them. Sometimes it is the volunteering of special skills. In the aftermath of the 2017 Mexico City earthquake, Mexican seismologists—who just happened to be in town for a major conference on the last disastrous Mexico City earthquake!—spent the next two weeks volunteering to inspect buildings for structural damage. And sometimes it is community-originated aid—this New Yorkerarticle about 2018’s prairie fires in Oklahoma focuses on the huge amount of post-disaster help which flowed in from all around the affected areas, often from people who had very little to spare themselves. In that article, the journalist Ian Frazier writes of the Oklahomans:', '“Trucks from Iowa and Michigan arrived with donated fenceposts, corner posts, and wire. Volunteer crews slept in the Ashland High School gymnasium and worked ten-hour days on fence lines. Kids from a college in Oregon spent their spring break pitching in. Cajun chefs from Louisiana arrived with food and mobile kitchens and served free meals. Another cook brought his own chuck wagon. Local residents’ old friends, retired folks with extra time, came in motor homes and lived in them while helping to rebuild. Donors sent so much bottled water it would have been enough to put out the fire all by itself, people said. A young man from Ohio raised four thousand dollars in cash and drove out and gave it to the Ashland Volunteer Fire Department, according to the Clark County Gazette. The young man said that God had told him to; the fireman who accepted the donation said that four thousand was exactly what it was going to cost to repair the transmission of a truck that had failed in the fire, and both he and the young man cried.”', 'These behaviors match the roles and responsibilities that members of a society display before the apocalyptic disaster. Ex-military volunteers reassemble in groups resembling military organizations; women in more patriarchal societies gravitate towards logistics and medical jobs while men end up taking more physical risks; firefighters travel to fight fires far away from their homes. The chef José Andrés served more than three million meals over three months after Hurricane Maria devastated Puerto Rico. Humans all over the world display this behavior after disasters. They display it consistently, no matter what kind of disaster is happening or what culture they come from.', 'What really happens after an apocalypse? Society works better than it ever had, for a brief time.', 'The writer Rebecca Solnit wrote an entire book about this phenomenon, and she called it A Paradise Built in Hell. She points out that it is really the fear on the part of powerful people that powerless people will react to trauma with irrational violence that is preventing us from seeing how apocalypse really shapes our societies. Solnit calls this ‘elite panic’, and contrasts it with the idea of ‘civic temper’—the utopian potential of meaningful community.', 'Apocalyptic science fiction tells us so much about how the future is going to hurt—or could. But it can also explore how the future will be full of spontaneous helping; societies that bloom for a night, a few weeks, a month, to repair what has been broken. The human capacity to give aid and succor seems to be universal, and triggered quite specifically by the disruption and horror of disaster. Science fiction might let us see that utopian potential more clearly, and imagine how we might help each other in ways we never knew we were capable of.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/if-the-human-species-were-to-near-extinction-would-we-join-together-or-fight-against-each-other/qotw0726-2/', '2020-07-26T12:00:00Z', '2020-07-26T12:00:00Z'),
  ('l6357', 'if-the-human-species-were-to-near-extinction-would-we-join-together-or-fight-aga', 'emma-s', 'name', null, array['Ever feel that stress makes you more cranky, hot-headed or irritable? For men in particular, we think of stress as generating testosterone-fueled aggression – thus instances of road rage, or the need to “blow off steam” after work with a trip to the gym or a bar. On the other hand, in circumstances of extreme stress such as during natural disasters like Hurricane Sandy, we hear moving accounts of people going out of their way to help others. Hurricane Sandy has led to a flourish of supportive tweets and Facebook messages directed to people on the East Coast. The tsunami in Asia a couple of years ago led to a huge influx of financial support to help afflicted areas. Many who lived in New York City during 9/11 remember that, for a few days afterward, the boundaries and class divisions between people dissolved: people greeted each other on the street and were more considerate, sensitive to each other, and gentle than normal.', 'The classic view is that, under stress, men respond with “fight or flight,” i.e. they become aggressive or leave the scene, whereas women are more prone to “tend and befriend,” as has been shown in research by Shelley Taylor. A new study by Markus Heinrichs and Bernadette von Dawans at the University of Freiburg, Germany, however, suggests that acute stress may actually lead to greater cooperative, social, and friendly behavior, even in men. This more positive and social response could help explain the human connection that happens during times of crises, a connection that may be responsible, at least in part, for our collective survival as a species.', 'In Heinrichs’ and Dawans’ study, male participants were assigned to either an experimental group, with a stress procedure (a public speaking exercise followed by a complicated mental arithmetics), or a control group with no stress. They all were then asked to play an economics game involving potential financial gain based on the choices they make. In this game, they could choose to cooperate with others and trust them or not. The researchers found that, rather than becoming more aggressive after stress, men in the stress group actually became more trusting of others, displayed more trustworthy behavior themselves, and were more likely to cooperate and share profits. The researchers also found that these results were not due to weakened judgment in the stress group: the stress group did not differ from the control groups in their ability to make decisions or their willingness to sanction another participant who behaved unfairly.', 'One reason why stress may lead to cooperative behavior is our profound need for social connection. Human beings are fundamentally social animals and it is the protective nature of our social relationships that has allowed our species to thrive. Decades of research shows that social connection is a fundamental human need linked to both psychological and and physical health including a stronger immune system, faster recovery from disease and even longevity.', 'Social connection may be particularly important under stress because stress naturally leads to a sense of vulnerability and loss of control. A study by Benjamin Converse and colleagues at the University of Virginia found that feeling out of control (through a reminder of one’s mortality) leads to greater generosity and helpfulness while research at Stanford University by Aneeta Rattan and Krishna Savani showed that the opposite is true when we are primed with feelings of self-determination and control. Think back to a time when you felt out of control, for example during a romantic break-up, when you had an empty bank account, or lost a job. Chances are your feeling of vulnerability and feelings of lack of control may have made you seek the comfort of others in some way. Brene Brown, Professor at the University of Houston Graduate College of Social Work and expert in the field of social connection, explains that vulnerability is a core ingredient of social bonding.', 'War is one of the greatest stresses anyone could ever encounter yet it also often leads to deep human friendships and incredible acts of heroism and sacrifice for one other. In my research with returning veterans, I have often heard them speak of the tight bond that occurs between servicemembers on the battlefield — one of the most stressful situations that exists. Countless soldiers have perished running into a line of fire to save an injured brother-in-arms. Some believe that it these experiences of profound human bonding that, despite the acute anguishes of war, makes some veterans long to return to war.', 'If stress leads to bonding, why then do we sometimes experience stress as making us cranky? The cause may be explained by a difference between acute and chronic stress. We know from research by Robert Sapolsky that acute stress prepares the body for resistance (physiological readiness, increased immune response, and heightened awareness) but that chronic stress slowly beats down the body. It may be that “acute” stress, i.e. a one-time stressful experience may lead to social bonding, as shown in the study, but that “chronic” stress, i.e. repeated exposure to stress over a long period, might wear us out. More research is needed to thoroughly examine the impact of chronic stress on social behavior.', 'Acute stress may help remind us of a fundamental truth: our common humanity. Understanding our shared vulnerability — life makes no promises — may be frightening, but it can inspire kindness, connection, and desire to stand together and support each other. Acute stress, as unpleasant as it may be, may also be an opportunity to experience the most beautiful aspects of life: social connection and love.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/if-the-human-species-were-to-near-extinction-would-we-join-together-or-fight-against-each-other/qotw0726/', '2020-07-26T12:00:00Z', '2020-07-26T12:00:00Z'),
  ('l6375', 'if-the-human-species-were-to-near-extinction-would-we-join-together-or-fight-aga', 'gaia', 'name', null, array['It depends on a couple factors. First, how plausible our survival is. If there is a clear way out – something tangible that we can do to avoid our extinction – we will band together. Second, if there is a common enemy, it will unify us enough to at least temporarily put our differences aside. Third, if something triggers enough people on a deep enough level, it can reach a tipping point that at least allows enough people to join together that they can overtake the antagonizing force (whether that be people themselves, an environmental catastrophe, or something else).', 'Regardless, I believe that reaching a point of near extinction is crucial in the awakening of our species – and thus, the planet and the universe. Take this metaphor – as the sun moves through the sky, you must move as you cannot stay in the shade all day. Right now, the Earth is facing a time where the light of truth has moved, and thus, is ending the shady darkness of delusion. It is forcing us to face it directly, in a way not before done. It is absolutely necessary to near extinction in order to unlock a deep, intuitive, passionate faith in our species and its existence. That awareness is necessary in order to take appropriate actions towards not going extinct. We are nearing a period of awakening through near extinction. It is an all out war of dark and light within our own beings. Yet, what is so far-out about it is that the war itself IS the awakening. The two polarities are necessary – they are in intercourse, union, perfect harmony. They, together, are the ground and sky, making up this world. Whether humans emerge on the other shore is less important – there is a greater force of awakening that propels the entire game we are playing.', 'So in conclusion, we CAN band together to avoid extinction. We may, we may not. The important recognition is that awakening and catastrophe are two sides of the same coin, and depend on one another. Regardless, consciousness will be evolving.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/if-the-human-species-were-to-near-extinction-would-we-join-together-or-fight-against-each-other/qotw0726-4/', '2020-07-27T12:00:00Z', '2020-07-27T12:00:00Z'),
  ('l6403', 'what-defines-good-leadership', 'big-dave', 'name', null, array['Like a good referee in sports, good leadership creates a container of freedom while also establishing clear boundaries. Then, they stay out of the affairs of those involved and are all but invisible. The wisest leaders understand that trust begets trust, and thus entrust their constituents with freedom and a hands-off style of governance. This is not as simple as not governing at all, but rather allowing the Universal current to govern without intervening. Thus, as the Taoist expression goes: Wei wu Wei – or ‘act, non-action’. This theme can be found in the Tao te Ching :', '‘The supreme rulers are hardly known by their subjects.', 'The lesser are loved and praised.', 'The even lesser are feared.', 'The least are despised.', 'Those who show no trust will not be trusted.', 'Those who are quiet value the words.', 'When their task is completed, people will say:', 'We did it ourselves.''']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/what-defines-good-leadership/what-defines-good-leadership/', '2020-08-02T12:00:00Z', '2020-08-02T12:00:00Z'),
  ('l6427', 'what-defines-good-leadership', 'chan-lee', 'name', null, array['During a meditation retreat, I asked my teacher: What does it mean to serve? He replied, ‘You’re always serving. The question is, what do you mean when you serve.’ His message resonated deeply – that I had a fixed idea in my head that one moment could be service and another could not be. How delusional that view all of a sudden became! ‘You’re always serving’, he said. ‘You’re always serving.’ Now, whenever consciously aware, I ask myself what I am in service to in THIS moment. In THIS moment.', 'To tie it full circle, I believe we are always in a leadership position just as we are always in service to something. Whether leading others or leading ourselves, the actions we take and thoughts we think have far-reaching effects. Our inextricable connection with others and to the whole of the planet means that there are no days off. To me, good leadership is a commitment to being one’s best possible self right now. This sacred commitment is contagious, and ultimately creates a community of beings riding the same wave of awakening and wellbeing.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/what-defines-good-leadership/qotw0816/', '2020-08-15T12:00:00Z', '2020-08-15T12:00:00Z'),
  ('l6425', 'what-defines-good-leadership', 'b-janszen', 'name', null, array['Shunryu Suzuki Roshi, a great Zen master, said: ‘Even though you try to put people under control, it is impossible. You cannot do it. The best way to control people is to encourage them to be mischievous. Then they will be in control in a wider sense. To give your sheep or cow a large spacious meadow is the way to control him. So it is with people: first let them do what they want, and watch them. This is the best policy. To ignore them is not good. That is the worst policy. The second worst is trying to control them. The best one is to watch them, just to watch them, without trying to control them.”', 'In my understanding, this means that the less one impedes the natural freedom of those whom one leads, the more they lead themselves (which is ultimately the key to obedience). The key is, as Suzuki Roshi says, to ‘watch them’. This is the most effective way, as it neither controls nor ignores, but instead treads the middle path of trust and presence.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/what-defines-good-leadership/what-defines-good-leadership-2/', '2020-08-15T12:00:00Z', '2020-08-15T12:00:00Z'),
  ('l6488', 'what-defines-good-leadership', 'big-dave', 'name', null, array['Taking responsibility for what you’re responsible for. Watch out for excuse-makers (and watch yourself to see if you’re one) — they make bad employees and bad friends.', 'Listening more than talking. Heed the adage that we have two ears and one mouth so we can listen twice as much as we speak. Those you speak with will felt “heard” and look forward to your next encounter.', 'Being humble. Under-promising and over-delivering. Putting yourself in other people’s shoes when you disagree with them. Surrounding yourself with people smarter than you. Knowing how and when to delegate — and when not to.', 'Recognizing that we all descended from the same single-celled organism and are made from the same cosmic dust….']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/what-defines-good-leadership/what-defines-good-leadership-3/', '2020-08-23T12:00:00Z', '2020-08-23T12:00:00Z'),
  ('l7199', 'what-defines-good-leadership', 'cnscsns', 'name', null, array['It is hard to over-emphasize the importance of one’s health in this precious, fragile, and short existence that we all take a swing at. The cliche phrase, ‘Health is Wealth’ is truly the case. More than money, material things, exciting plans, or anything else really, our health is the most valuable currency. That goes for physical, mental, and emotional health. But what exactly do we mean by ‘health’?', 'As I see it, health is multi-faceted. As human beings, besides certain anomalies such as wisdom teeth, appendicitis’, etc, we have evolved to survive and thrive in our Earthly environment. It is largely human-induced blockages that impede this connection and balance. Blockages such as mental illness, poor diet, lathargic lifestyles, and societies designed in disconnection from Earth and each other (to name a few). In other words, we pulled ourselves out of the universal flow of alignment and created an alternative model hung together by sticks and glue.', 'This being said, we have the capacity to make the necessary adjustments to re-align in good all-around health. We can treat our bodies better – with more exercise, play, a better diet, more physical intimacy, etc. We can treat our mind better with practices of mindfulness, gratitude, compassion, etc. We can restore emotional stability with these practices as well. All of these facets of ‘wellbeing’ are profoundly interconnected. They affect each other. So it really takes all of the parts moving in harmony to emerge a fully-healthy being.', 'We all have the capability to imagine, practice, and restore ‘good health’. From here, we can not just survive but thrive. The human capability is boundless. I hope there comes a day where our species aligns in this state of wellbeing.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/what-defines-good-health/qotw0314-c/', '2021-03-14T12:00:00Z', '2021-03-14T12:00:00Z'),
  ('l7195', 'what-defines-good-leadership', 'greg-a', 'name', null, array['Wellbeing [ noun ] – the state of being comfortable, healthy or happy. This is what the Oxford English Dictionary defines as wellbeing, but what does that actually mean? The short answer is… well, there is no short answer! What one person feels is their perfect state of wellbeing may be completely different from another person. This stands to reason as we all have different goals, ambitions and personalities.', 'Each aspect of being comfortable, healthy and happy also has many different facets that can be taken subjectively. For example, the English Oxford Dictionary’s definition mentions happiness. However, wellbeing as a concept is much broader than this and has been debated since the Third Century BC. The Philosopher Aristotle came up with the concept of Eudaimonia – the contented state of feeling healthy, happy and prosperous. Even though happiness is an integral part of your personal wellness, it includes other things such as the fulfillment of long-term goals, your sense of purpose and how in control you feel in life.', 'The meaning of wellbeing is multidimensional', 'An overall sense of wellness will not be achieved without having a balance in these key elements:', '• Physical. This includes lifestyle choices that affect the functioning of our bodies. What we eat and how active we are will affect our physical wellbeing.', '• Emotional or psychological. This is our ability to cope with everyday life and reflects how we think and feel about ourselves.', '• Social. This is the extent that we feel a sense of belonging and social inclusion. The way we communicate with others, our relationships, values, beliefs, lifestyles and traditions are all important factors of social wellbeing.', '• Spiritual. This is the ability to experience and integrate meaning and purpose in life. Achieved through being connected to our inner self, to nature or even a greater power.', '• Intellectual. It is important to gain and maintain intellectual wellness as it helps us to expand our knowledge and skills in order to live an enjoyable and successful life.', '• Economic. Economic wellness, in short, is our ability to meet our basic needs and feel a sense of security.', 'The world we live in is complex. Understanding the requirement of wellness and the factors that influence this state, whether as an individual, community or nation, helps us to work together to improve the quality of our lifestyles. Five simple ways to improve our overall wellness are:', 'Connect – talk and listen to others and always live in the moment.
Be active – do what you can and enjoy what you do. 
Take notice – remember the simple things that give you joy.
Keep learning – embrace new experiences and seek new opportunities.
Give – give people your time, your words and your presence.', '“Wellness is the complete integration of body, mind and spirit. The realisation that everything we do, think, feel and believe has an effect on our wellbeing']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/what-defines-good-health/qotw0314-2/', '2021-03-14T12:00:00Z', '2021-03-14T12:00:00Z'),
  ('l7191', 'what-defines-good-leadership', 'lauren-h', 'name', null, array['What does being healthy mean to you? The World Health Organization (WHO) defines health as “complete physical, mental, and social well-being – and not merely the absence of disease or infirmity.” But research suggests that, despite this, Americans may still define health in a narrow way.', 'In new research presented during the Diet and Exercise in a Social World session at the SPSP Annual Convention today, Danielle Boles and her colleagues asked Americans what being healthy means. People overwhelmingly mentioned “the absence of illness,” neglecting other factors. In some cases, Americans defined health as what they did not have. For instance, people who defined health as “mental balance” were those who worried the most and got the least sleep. Could defining health by what we’re struggling to get lead to stress, ultimately undermining health?', 'We may also have narrow ideas about where we can be healthy. The WHO stresses that physical activity is crucial for health – but exercising seems unusual in many everyday settings. Research by Andrew Ward found that people view exercise as something that you can’t do everywhere. For instance, people reported that it would be almost as unusual to see someone doing jumping jacks in an airport as someone setting a car on fire! This might stop people from thinking about everyday opportunities for exercise.', 'Many health messages target obesity. For instance, the WHO calls it a global epidemic. Obesity is indeed one of America’s biggest health problems. But focusing on weight might have unintended consequences. Overweight people face social disapproval, such as being seen as lazy, weak-willed, or worthless. Research by Angelina Incollingo Rodriguez and others suggests that dealing with social disapproval could make overweight people unhealthier. The researchers gave people with normal body weight the experience of being overweight by having them wear fat suits. When wearing a fat suit, people ate more unhealthy food: 191 more calories of M&Ms, potato chips, and soda. Focusing too much on weight in definitions of health might lead to a vicious cycle.', 'So what can we do? Broadening definitions of healthiness to might have benefits. A growing body of researchshows that social ties are as important for our health as diet and exercise. Boles and her colleagues explored whether people see what you have to do to be healthy as “social” or “isolating.” When people believed health is social, rather than isolating, they had healthier behaviors. The importance of social connection has become a focus of some recent healthcare campaigns. Kaiser Permanente’s “Thrive” campaign features ads that say “Make time for we time” and “Hugs are healthy.”', 'Acknowledging the role that our social lives play in healthcare settings could be one important step forward for healthcare in the United States.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/what-defines-good-health/qotw0314/', '2021-03-14T12:00:00Z', '2021-03-14T12:00:00Z'),
  ('l6418', 'how-do-you-remain-compassionate-in-a-time-of-conflict', 'nick-s', 'name', null, array['[et_pb_section fb_built=”1″ admin_label=”section” _builder_version=”4.4.7″ hover_enabled=”0″ background_color=”rgba(0,0,0,0)” da_is_popup=”off” da_exit_intent=”off” da_has_close=”on” da_alt_close=”off” da_dark_close=”off” da_not_modal=”on” da_is_singular=”off” da_with_loader=”off” da_has_shadow=”on” da_disable_devices=”off|off|off”][et_pb_row admin_label=”row” _builder_version=”3.25″ background_size=”initial” background_position=”top_left” background_repeat=”repeat”][et_pb_column type=”4_4″ _builder_version=”3.25″ custom_padding=”|||” custom_padding__hover=”|||”][et_pb_text admin_label=”Text” _builder_version=”3.27.4″ background_size=”initial” background_position=”top_left” background_repeat=”repeat”]
The Tao te Ching says:', '“There is no greater misfortune
than underestimating your enemy.
Underestimating your enemy
means thinking that he is evil.
Thus you destroy your three treasures
and become an enemy yourself.
When two great forces oppose each other,
the victory will go
to the one that knows how to yield.” 
― Lao Tzu, Tao Te Ching', 'Conflict is the friction necessary for growth. Suzuki Roshi, the Zen master, says that a true teaching is painful because it is highlighting where we are vulnerable. During times of conflict, rather than the traditional approach of seeing it as something negative and a hindrance to wellbeing, awakened beings approach adversity with appreciation and gratitude.', 'Compassion is a necessary aspect of any successful conflict transformation. The reason is that successful conflict transformation requires both parties to be re-directed towards growth. It is a collective effort, just as a competitive tennis match is both competition and cooperation. Overall, this theme of cooperative adversity is easier said than done, however it is unquestionably an important skill for navigating relationships, vocation, and ultimately life as a whole.', '[/et_pb_text][/et_pb_column][/et_pb_row][/et_pb_section]']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/how-do-you-remain-compassionate-in-a-time-of-conflict/qotw0809-2/', '2020-08-14T12:00:00Z', '2020-08-14T12:00:00Z'),
  ('l6413', 'how-do-you-remain-compassionate-in-a-time-of-conflict', 'alexandra-t', 'name', null, array['It’s impossible to run a successful startup without working with other people, and when you work with other people there’s always some level of conflict. Conflict can be intimidating, anxiety-inducing and exhausting.', 'I’ve spent a lot of time, as an entrepreneur and as a human, trying to avoid conflict. But the reality is that conflict is an entirely natural part of any human relationship, and if you manage it with caution and empathy, conflict can even make your work better.', 'According to a number of studies, minority dissent within teams makes everyone reconsider their assumptions and seek new information which leads to better decisions.', 'In my business, I’ve found that miscommunication is often at the root of conflict. Before we were business partners, the members my team of four were coworkers, friends and college classmates. So we knew each other pretty well before we went into business together.Recommended For You', 'Sometimes the history we have with each other comes in handy– we know who we are and are comfortable with each other. But other times how well we know each other leads us to make incorrect assumptions which lead to conflict.', 'Whenever team conflict came up, a mentor of mine used to say, “Everybody tells themselves stories.” What he meant was that when complicated situations occur on and around teams, every member tells themselves a story about the situation. They make assumptions about how their team members are feeling, and they’re often wrong.', 'I know personally that instead of voicing some of those concerns or asking others how they are feeling and having a dialogue, I often try and avoid confrontation.', 'But two years into running my startup, I’ve learned that the anxiety and conflict that comes from avoiding confrontation is a million times worse than actual confrontation.', 'Here are three simple ways to make those conversations their best:', '1 – Don’t wait', 'Issues or tensions never come up at a convenient time. Sometimes their timing makes no sense, but other times it’s directly related to a stressor within your business. In the past, conflict has often arisen when my team needs to make a big decision or change. When we’re in the normal swing of our work, we’re fine. But when we’re treading new waters, we all get stressed and communication can break down.', 'When you’re in those situations, particularly if you’re on a deadline, the tendency is to want to push conflict resolution off until you can get the work done. But if you don’t address the situation right away, then the work you do get done will suffer. So if there is any conflict within your team, you need to sit down and hash it out immediately. The longer that people have to tell themselves their stories, the more complicated and entrenched problems will become.', '2 – Treat people like people', 'In entrepreneurship it’s easy to blur the line between personal and work time because building a company takes a lot of time and work. So naturally it’s impossible to separate personal stresses from work ones.', 'It’s been important to me to maintain friendships with my teammates. Knowing what’s going on in their lives helps me to understand where we’re at in our business relationship. When people have bad days at home they blend into bad days at work. And when people have bad days at work they blend into bad days at home.', 'That’s one reason (the other is just because we’re friends) that we always start and end our business meetings asking each other about their lives. We catch up on who’s getting married and who’s traveling and how we’re all doing. Staying on top of people’s lives helps to know when to alleviate people’s work load.', 'It’s easy to fall into expectations of teammates that put work at the constant priority. But you have to let people be people and let them have emotions and feelings and accept that those things make them better teammates.', '3 – Find a way to come to consensus', 'You can’t walk away from a conflict without solving it. Not everybody needs to agree on every point, but everybody needs to agree on a way to move forward. In a perfect situation, there’s someone who can mediate the conversation who isn’t involved in the conflict. Sometimes that requires bringing in an outsider who can be neutral.', 'It’s important to hash everything out and give everyone a chance to speak their mind. But at some point the mediator needs to draw the line and say, “Okay we have all the information, what are we going to do to resolve this situation?']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/how-do-you-remain-compassionate-in-a-time-of-conflict/qotw0809/', '2020-08-14T12:00:00Z', '2020-08-14T12:00:00Z'),
  ('l6421', 'how-do-you-remain-compassionate-in-a-time-of-conflict', 'gaia', 'name', null, array['This is from the Dalai Lama:', '‘If we have been reborn time after time, it is evident that we have needed many mothers to give birth to us…. the first cause bringing about bodhicitta is the recognition that all beings have been our mother. The love and kindness shown us by our mother in this life would be difficult to repay. She endured many sleepless nights to care for us when we were helpless infants. She fed us and would have willingly sacrificed everything, including her own life, to spare ours.', 'As we contemplate her example of devoted love, we should consider that each and every being throughout existence has treated us this way. Each dog, cat, fish, fly, and human being has at some point in the beginningless past been our mother and shown us overwhelming love and kindness. Such a thought should bring about our appreciation.', '…if all other sentient beings who have been kind to us since beginningless time are suffering, how can we devote ourselves to pursuing merely our own happiness? To seek our own happiness in spite of the suffering others are experiencing is tragically unfortunate. Therefore, it is clear that we must try to free all sentient beings from suffering.’', 'This level of compassion and awareness makes 99 percent of our conflicts seem as small as dewdrops on a blade of grass – gone as soon as the sun touches them. For the larger conflicts, this vantage point encircles the conflict in noble qualities such as compassion, gratitude, and wisdom. Thus, the stage is set to make progress towards awakening and ease suffering rather than multiplying it as conflict can easily do.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/how-do-you-remain-compassionate-in-a-time-of-conflict/qotw0809-3/', '2020-08-15T12:00:00Z', '2020-08-15T12:00:00Z'),
  ('l6480', 'what-is-the-value-of-a-human-life-in-2020', 'delerium', 'name', null, array['$10 million. At least that’s the figure that was generated by Kip Viscusi, an economist from Vanderbilt University. Viscusi derives this value from safety regulations in organizations like the CDC, EPA, and department of transportation. This figure is based on American lives, not global. But before we get too hyped on being worth millions, let’s consider the honest reality of this. Jeff Bezos is worth $200 billion, and the homeless man on the corner has $10 dollars to his name. We can put a price-tag on a human life, but that does not mean the price is fair.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/what-is-the-value-of-a-human-life-in-2020/what-is-the-value-of-a-human-life-in-2020-2/', '2020-08-23T12:00:00Z', '2020-08-23T12:00:00Z'),
  ('l6478', 'what-is-the-value-of-a-human-life-in-2020', 'shay-p', 'name', null, array['There is no concrete ‘minimum wage’ on a human life in 2020. There never has been, and there still is not today. Just yesterday, multi-millionaire Lori Loughlin was sentenced to just two months in prison for paying bribes to get her daughters into USC, while Crystal Mason, a black mother of three, was sentenced to five years for voting when she didn’t realize a past felony conviction made her ineligible. A life’s value is a product of their fortune and fame, cloaked in the illusion of their benefit to the world. Simply put, if you have money, you are more likely to survive and be remembered. You can afford the necessary healthcare for most illnesses and injuries, the healthiest food, and many other amenities. And say you work yourself to death, you can buy plaques, donate money, and leave a financial legacy behind.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/what-is-the-value-of-a-human-life-in-2020/what-is-the-value-of-a-human-life-in-2020/', '2020-08-23T12:00:00Z', '2020-08-23T12:00:00Z'),
  ('l6507', 'who-really-runs-the-world', 'the-kid', 'name', null, array['It seems that, in the hierarchy of power, the top of the pyramid is untraceable. You say politicians are in charge, as they are the ones signing documents into law. Then you go one step further, and say that big business is in charge, as they are the ones funding the politicians. Then you go one step further and say that bankers are in charge, as they control the money supply. Then you take it one step further, and say that there is a secret coalition of beings controlling everything, who remain nameless and mysterious to the rest of the public. From there, conspiracies abound. Just about anything is possible.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/who-really-runs-the-world/who-really-runs-the-world/', '2020-08-29T12:00:00Z', '2020-08-29T12:00:00Z'),
  ('l6504', 'who-really-runs-the-world', 'michael-b', 'name', null, array['Who really runs the world? We’re not talking in a power-brokers-conspiring-in-the-back-room sort of way. Rather, by looking at the institutions that countries themselves have set up to organize the world’s affairs, can we determine who is doing most of the managing?', 'That’s the question Eric Werker, associate professor in the Business, Government, and the International Economy unit at Harvard Business School, asks in a new working paper, Who Runs the International System? Power and Staffing at the United Nations Secretariat. He conducted the research with Dartmouth College Assistant Professor of Economics Paul Novosad.', 'Among their findings: Powerful countries including the United States, China, and India have less administrative influence than you might think , while small but rich democracies such as Finland and New Zealand are overrepresented.', 'Does it matter?', '“There are two views of the United Nations,” says Werker. “Either you think it matters or you don’t.”', 'In the first camp are those who believe that the United Nations has real influence on the world by setting rules and norms between nations. “Just the conversations that are happening in the UN are important in determining international priorities—do we go after landmines, or gender disparity, or corruption? Any of these decisions will help some countries and hurt others.”', 'In the other camp are those who believe that despite all of these powers, the United Nations merely reflects the agendas of the states within it.', 'Either way, the national makeup of senior positions that run the United Nations can tell us a lot about which countries are actually calling the shots in world affairs. “Even if you think the UN is merely reflecting the world order instead of creating it, you should still know who is running it,” says Werker.', 'Although the United Nations Secretariat, the executive arm of the organization, has some 43,000 employees worldwide, most of the strategic decisions are made by 80 or so senior members. Headed by the Secretary-General, the Secretariat plays key roles in agenda-setting for various deliberative UN organizations and manages global peace-keeping operations—including the UN’s response to the Ebola outbreak. There is keen competition and string pulling among nations to win those upper level staff appointments.', 'While those members, in theory, are supposed to check their national allegiances at the door, in practice that’s not the case, says Werker. “Both the UN’s own analysis and remarks by diplomats over the decades have indicated nations really do act in their own national interest.”', 'By looking at the national composition of Secretariat staffing over the years, Werker hypothesized that it is possible to show the changing nature of world power, providing another and perhaps better way to measure international influence than traditional measures such as counting the number of tanks and bombs countries possess. “War, thankfully, is a very rare event,” he says. “When two countries do go to war, it means that one of them has miscalculated. By contrast, in this setting you have a constant struggle in real time between every nation in the world vying for influence within the Secretariat.”', 'In order to figure out who has been winning that competition, Werker and Novosad consulted the Yearbook of the United Nations. They constructed a database of every senior official in the Secretariat from 1945 to 2008—some 4,000 names in all. Then, consulting news reports and international directories, they determined the nationality of each of those officials.', 'Finally, Werker and Novosad compared the percentage of officials from each country to the percentage of that country’s world population in order to determine the amount to which a nation was overrepresented in the Secretariat, “who was punching above their weight,” says Werker. When they did so, a small number of demographically similar countries came out on top.', 'The small, the rich, the Nordic', '“We found a handful of smaller, richer, democracies most represented by this metric, including Sweden, Norway, and Finland,” he says. Rounding out the top five were two other small, rich, democracies — New Zealand and Ireland. In the top 10 also appeared Denmark and Switzerland, along with seeming long shots, Panama, Jamaica, and Uruguay.', 'Werker wasn’t surprised about the overrepresentation of Scandinavian countries, given their high rankings for education and low rankings for corruption. “The mandate of the UN on staffing is supposed to rest on three things: competence, integrity, and the third being national representation,” Werker says.', 'Even when controlling for the first two measures, the top countries shared other characteristics. Chief among them were willingness to make investments in international diplomacy—both in terms of their number of consulates and embassies and the amount of money they put in diplomatic efforts. While military spending also correlated with influence in the early years of the institution, it has been less of an indicator in more recent years, says Werker.', 'Instead, the countries that seem to be overrepresented reflect a kind of “soft power,” more adept at working behind the scenes in international institutions.', '“At HBS we talk about different kinds of leadership, and sometimes the best leaders are those who rarely have to do or say anything, but can be very effective through quiet example-setting,” says Werker. “Maybe we just trust Scandinavians to be nice neutral parties to undertake these jobs, which is the ultimate soft power compliment, where you don’t even think they are working in their national interest. That doesn’t mean if push came to shove, they would win a military battle, but the best kind of war is one you don’t have to fight.”', 'Less influence for US, China', 'As for the United States, even though it still represents the largest country in terms of actual representation, its UN-related influence has steadily waned relative to population. At least until the 1980s, that didn’t seem to matter, says Werker, since its voting record matched that of allies that maintained high degrees of representation. In the past 35 years, however, the US has diverged from positions of its allies, leading to a decline in its relative power within the organization.', 'Perhaps the most surprising finding in the survey is the degree to which burgeoning economic powers such as Brazil, India, and China, have remained underrepresented in the Secretariat—ranking 83, 89, and 95 respectively.', '“You can look at this in two ways,” says Werker. “Either in spite of being a military and economic power, these countries haven’t yet been able to project soft power. Or, you can take another view, that these countries are rejecting the global system. Either way, it’s not clear that it’s in the best interest of the world for these rising powers to take a back seat when it comes to solving international conflicts.”', 'Then again, says Werker, it took Germany and Japan many years after World War II in order to reach higher levels of representation, and both countries still lag compared to other G8 countries such as the United Kingdom, France, and Canada.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/who-really-runs-the-world/qotw-0830/', '2020-08-29T12:00:00Z', '2020-08-29T12:00:00Z'),
  ('l6531', 'are-things-worse-or-better-than-theyre-being-portrayed', 'kai-b', 'name', null, array['If you watch the news, you’re bound to think things are pretty darn bad. If you look at statistics, especially those around quality of life, war, freedom, etc, you are likely to see that things are better than they used to be. If you look at the racial injustice, climate change, and political leadership, you’ll probably feel pretty grim. However, if you hear the spiritual rhetoric about the evolution of consciousness, great awakening, birthing of a new age, etc, you may feel optimism once more. In short, ‘better’ and ‘worse’ are dualistic, subjective terms. They are not concrete – rather, they depend on your vantage point. The only common denominator is that there is great change, just as there always has been. Change is occurring in every bit of matter, every corner of consciousness, every nook and cranny of existence. Given this, we must not grasp at smoke – that is to say, hold onto a model of ‘good’ or ‘bad’, ‘better’ or ‘worse’. All we can do is accept present circumstances, study past trends, and envision a future that aligns with our deepest truths.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/are-things-better-or-worse-than-theyre-being-portrayed/are-things-worse-or-better-than-theyre-being-portrayed/', '2020-09-10T12:00:00Z', '2020-09-10T12:00:00Z'),
  ('l6528', 'are-things-worse-or-better-than-theyre-being-portrayed', 'tom-s', 'name', null, array['When you read the news, sometimes it can feel like the only things reported are terrible, depressing events. Why does the media concentrate on the bad things in life, rather than the good? And what might this depressing slant say about us, the audience?', 'It isn’t that these are the only things that happen. Perhaps journalists are drawn to reporting bad news because sudden disaster is more compelling than slow improvements. Or it could be that newsgatherers believe that cynical reports of corrupt politicians or unfortunate events make for simpler stories. But another strong possibility is that we, the readers or viewers, have trained journalists to focus on these things. Many people often say that they would prefer good news: but is that actually true?', 'To explore this possibility, researchers Marc Trussler and Stuart Soroka, set up an experiment, run at McGill University in Canada. They were dissatisfied with previous research on how people relate to the news – either the studies were uncontrolled (letting people browse news at home, for example, where you can’t even tell who is using the computer), or they were unrealistic (inviting them to select stories in the lab, where every participant knew their choices would be closely watched by the experimenter). So, the team decided to try a new strategy: deception.', 'Trick question', 'Trussler and Soroka invited participants from their university to come to the lab for “a study of eye tracking”. The volunteers were first asked to select some stories about politics to read from a news website so that a camera could make some baseline eye-tracking measures. It was important, they were told, that they actually read the articles, so the right measurements could be prepared, but it didn’t matter what they read.', 'After this ‘preparation’ phase, they watched a short video (the main purpose of the experiment as far as the subjects were concerned, but it was in fact just a filler task), and then they answered questions on the kind of political news they would like to read.', '(flash.pro/Flickr/CC BY 2.0)', 'The results of the experiment, as well as the stories that were read most, were somewhat depressing. Participants often chose stories with a negative tone – corruption, set-backs, hypocrisy and so on – rather than neutral or positive stories. People who were more interested in current affairs and politics were particularly likely to choose the bad news.', 'And yet when asked, these people said they preferred good news. On average, they said that the media was too focussed on negative stories.', 'Danger reaction', 'The researchers present their experiment as solid evidence of a so called “negativity bias“, psychologists’ term for our collective hunger to hear, and remember bad news.', 'It isn’t just schadenfreude, the theory goes, but that we’ve evolved to react quickly to potential threats. Bad news could be a signal that we need to change what we’re doing to avoid danger.', 'As you’d expect from this theory, there’s some evidence that people respond quicker to negative words. In lab experiments, flash the word “cancer”, “bomb” or “war” up at someone and they can hit a button in response quicker than if that word is “baby”, “smile” or “fun” (despite these pleasant words being slightly more common). We are also able to recognise negative words faster than positive words, and even tell that a word is going to be unpleasant before we can tell exactly what the word is going to be.', 'We tend to pay more attention to negative words in headlines (Getty Images)', 'So is our vigilance for threats the only way to explain our predilection for bad news? Perhaps not.', 'There’s another interpretation that Trussler and Soroka put on their evidence: we pay attention to bad news, because on the whole, we think the world is rosier than it actually is. When it comes to our own lives, most of us believe we’re better than average, and that, like the clichés, we expect things to be all right in the end. This pleasant view of the world makes bad news all the more surprising and salient. It is only against a light background that the dark spots are highlighted.', 'So our attraction to bad news may be more complex than just journalistic cynicism or a hunger springing from the darkness within.', 'And that, on another bad news day, gives me a little bit of hope for humanity.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/are-things-better-or-worse-than-theyre-being-portrayed/qotw0906-2/', '2020-09-10T12:00:00Z', '2020-09-10T12:00:00Z'),
  ('l6525', 'are-things-worse-or-better-than-theyre-being-portrayed', 'joshua-r', 'name', null, array['Was the past good or bad? Are we on the right track or the wrong one? Is life getting better or worse? These questions are easy to ask—pollsters and politicians love asking them—but surprisingly hard to answer. Most historical and statistical evidence shows that life used to be shorter, sicker, poorer, more dangerous, and less free. Yet many people have fond memories of bygone years, and wonder if reports of their awfulness have been exaggerated. Others concede that life used to be worse in some ways, but wonder if it wasn’t also better in others—simpler, more predictable, more spiritual. It’s common to appreciate modernity while fearing its destructive potential. (Life expectancy may be higher today, but it will be shorter after the nuclear-climate-bioterror apocalypse.) If being alive now doesn’t feel particularly great, perhaps living in the past might not have felt particularly bad. Maybe human existence in most times and places is a mixed bag.', 'Last year, the Pew Research Center asked people around the world whether life had been better or worse in their countries fifty years ago. A slim plurality of Americans said they thought life had been better. In 1967, the United States was embroiled in the Vietnam War. Protest marches were taking place around the country, crime was surging, and race riots were breaking out in Detroit, Newark, Milwaukee, and other cities. That spring, a wave of tornadoes injured thousands across the Midwest; members of the Black Panther Party, carrying shotguns and rifles, marched into the California statehouse to protest a racially motivated gun-control law. In June, the Six-Day War broke out. Americans lived in smaller houses, ate worse food, worked more hours, and died, on average, seven years earlier. On the other hand, nasa launched several moon probes and Jimi Hendrix’s “Are You Experienced” helped launch the Summer of Love. By an obscure retrospective calculus, the good appears to balance out the bad. Frightening events seem less so in retrospect. Memory is selective, history is partial, and youth is a golden age. For all these reasons, our intuitive comparisons between the past and the present are unreliable. Many Americans living in 1967 might well have thought that life had been better in 1917.', 'Nor is this just an American inclination. In “Enlightenment Now: The Case for Reason, Science, Humanism, and Progress,” the cognitive scientist Steven Pinker looks at recent studies and finds that majorities in fourteen countries—Australia, Denmark, Finland, France, Germany, Great Britain, Hong Kong, Malaysia, Norway, Singapore, Sweden, Thailand, the U.A.E., and the United States—believe that the world is getting worse rather than better. (China is the only large country in which a majority expresses optimism.) “This bleak assessment of the state of the world is wrong,” Pinker writes—and not just a little wrong but “wrong wrong, flat-earth wrong.”', 'Because our ideas about human progress are so vague, it’s tempting to think they don’t matter. But “Is life getting better or worse?” may be a dorm-room debate with consequences. It has affected our politics, Pinker says, encouraging voters to elect unproved leaders “with a dark vision of the current moment.” He quotes from Donald Trump’s Inaugural Address, in which the President bemoaned “mothers and children trapped in poverty . . . an education system which leaves our young and beautiful students deprived of all knowledge . . . and the crime, and the gangs, and the drugs.” In fact, poverty, crime, and drug abuse are declining in America, and our educational system, though flawed, is one of the best in the world. Pessimism can be a self-fulfilling prophecy. By believing that the world is getting worse, Pinker argues, we can make it so.', 'It’s also possible to take this reasoning to an extreme—to become radically pessimistic about the consequences of pessimism. In “Suicide of the West,” the conservative intellectual Jonah Goldberg argues that progressive activists—deluded by wokeness into the false belief that Western civilization has made the world worse—are systematically dismantling the institutions fundamental to an enlightened society, such as individualism, capitalism, and free speech. (“Sometimes ingratitude is enough to destroy a civilization,” Goldberg writes.) On the left, a parallel attitude holds sway. Progressives fear the stereotypical paranoid conservative—a nativist, arsenal-assembling prepper whose world view has been formed by Fox News, the N.R.A., and “The Walking Dead.” Militant progressives and pre-apocalyptic conservatives have an outsized presence in our imaginations; they are the bogeymen in narratives about our mounting nihilism. We’ve come to fear each other’s fear.', 'With “Enlightenment Now,” Pinker hopes to return us to reality. In the course of five hundred pages, he presents statistics and charts showing that, despite our dark imaginings, life has been getting better in pretty much every way. Around the globe, improved health care has dramatically reduced infant and maternal mortality, and children are now better fed, better educated, and less abused. Workers make more money, are injured less frequently, and retire earlier. In the United States, fewer people are poor, while elsewhere in the world, and especially in Asia, billions fewer live in extreme poverty, defined as an income of less than a dollar and ninety cents per day. Statistics show that the world is growing less polluted and has more parks and protected wilderness. “Carbon intensity”—the amount of carbon released per dollar of G.D.P.—has also been falling almost everywhere, a sign that we may be capable of addressing our two biggest challenges, poverty and climate change, simultaneously.', 'Pinker cites statistics showing that, globally, there are now fewer victims of murder, war, rape, and genocide. (In his previous book, “The Better Angels of Our Nature,” he attributed this development to a range of causes, such as democratization, pacifism, and better policing.) Life expectancy has been rising, and—thanks to regulations and design improvements—accidental deaths (car crashes, lightning strikes) are also in steep decline. Despite what we’re often told, students today report being less lonely than in the past, and, although Americans feel overscheduled, studies show that men and women alike have substantially more leisure time than their parents did (ten and six hours more per week, respectively).', '“Enlightenment Now” seems designed to reassure both Republicans, who worry about increasing drug use and terrorism, and Democrats, who see racism and sexism as the crises of our time. Despite fears of resurgent racism, the number of hate crimes in America has been falling for decades, while analyses of Internet searches, which reveal searchers’ hidden interests, indicate that racist, sexist, and homophobic attitudes are also in retreat. What Pinker calls “emancipative values”—tolerance, feminism, and so on—are becoming more common even in old-fashioned societies. (Young people in the Middle East now hold social views comparable to the ones held by young Western Europeans in the nineteen-sixties.) Although there’s been a recent surge in drug overdoses in the U.S., most of those who die belong to “the druggy Baby Boomer cohort . . . born between 1953 and 1963.” Drug and alcohol use among teen-agers—with the exception of cannabis and vaping—is at its lowest level since 1976.', 'Pinker’s message is simple: progress is real, meaningful, and widespread. The mystery is why we have so much trouble acknowledging it. Pinker mentions various sources of pessimism—the “progressophobia” of liberal-arts professors, for instance—but directs most of his opprobrium toward the news media, which focus almost entirely on of-the-moment crises and systematically underreport positive, long-term trends. (Citing the German economist Max Roser, Pinker argues that a truly evenhanded newspaper “could have run the headline number of people in extreme poverty fell by 137,000 since yesterday every day for the last twenty-five years.”) He consults the work of Kalev Leetaru, a data scientist who uses “sentiment mining,” a word-analysis technique, to track the mood of the news; Leetaru finds that, globally, journalism has grown substantially more negative.', 'The power of bad news is magnified, Pinker writes, by a mental habit that psychologists call the “availability heuristic”: because people tend to estimate the probability of an event by means of “the ease with which instances come to mind,” they get the impression that mass shootings are more common than medical breakthroughs. We’re also guilty of “the sin of ingratitude.” We like to complain, and we don’t know much about the heroic problem-solvers of the past. “How much thought have you given lately to Karl Landsteiner?” Pinker asks. “Karl who? He only saved a billion lives by his discovery of blood groups.”', 'Even as “Enlightenment Now” celebrates our ingenuity, it suggests that there’s something bratty about humankind: we just don’t want to admit how good we have it. In “It’s Better Than It Looks: Reasons for Optimism in an Age of Fear,” the journalist Gregg Easterbrook offers a wider-ranging account of our pessimism. In his view, it’s the result of various demographic, cultural, and political trends. The country is aging, and older people tend to be nostalgic and grumpy. Reaganism made “ritualized denunciation” of the government routine, encouraging cynicism among conservatives; among liberals, a focus on marginalized groups has led to the competitive articulation of suffering, creating a culture of “majority victimhood,” in which every group trumpets its grievances. “Claims for liability and compensation have increased,” Easterbrook notes, reflecting the rise of a punitive society obsessed with the assignment of blame; fewer people attend worship services, where they might hear messages of hope or have uplifting interactions with neighbors. Thanks to cable news, talk radio, and social media, “society has opinionized,” and it’s now “expected that all will possess strong views”; this has fed the rise of “catastrophism,” or the continual overstatement of what’s wrong. (“Everything is terrible” is a stronger view than “Things are pretty decent.”) Finally, technology has changed. Easterbrook cites psychological research suggesting that the physical proximity of our smartphones gives them uncanny power to influence our moods. It’s one thing to see an alarming headline on a TV across the room, and another to feel it vibrating in your pocket.', 'Perhaps we’ve come to see history itself as one bad news cycle after another. The word “history” used to evoke “traditions to be respected, legacies to be transmitted, knowledge to be elaborated, or deaths to be commemorated,” the French historiographer Henry Rousso points out, in “The Latest Catastrophe: History, the Present, the Contemporary.” After the traumas of the twentieth century, however, we began to define our historical era by “the most lethal moments of the near past”—the conflicts, wars, and atrocities that “have had the most difficulty ‘passing away.’ ” We “delimit the contemporary era” by referring to “the ends of wars or sometimes the beginnings of wars: the end of World War I, the end of World War II, the end of the Cold War.” (In America, we talk about the Vietnam era and the generation born after 9/11.) “Since 1945, all contemporary history begins with ‘the latest catastrophe,’ ” Rousso concludes. We see the past in terms of crises, and imagine the future that way, too.', 'Pessimism may even answer to our spiritual needs. The philosopher Charles Taylor, in his book “A Secular Age,” from 2007, argued that modern life is characterized by a sense of individual spiritual obligation. In pre-Reformation Europe, ordinary people were held to lower spiritual standards than monks, priests, and nuns, and a member of the laity might live an imperfect, worldly life and still be saved, as long as he supported, through prayer or alms, the work of the “virtuosi.” Such a system, Taylor writes, “involved accepting that masses of people were not going to live up to the demands of perfection.” Eventually, Protestantism intervened, making individuals responsible for their own salvation. In the new way of life that emerged, religion was democratized, and each person was charged with spiritual self-stewardship. Part of this shift involved a political credo. In Taylor’s précis: “We are all responsible for each other, and for society as a whole.”', 'Today, we tend to conceive the credo of social responsibility as an ethical idea, justifiable on secular grounds. Still, it remains tied to an inner, devotional imperative. We know that we accomplish little by reading the news, and sense that our infinite, tragic news feeds distort, rather than enhance, our picture of reality. Still, it feels wrong to outsource the work of salvation to Bill and Melinda Gates, and presumptuous to trust too much in the power of good works. Pessimism can be a form of penance, and of spiritual humility in a humanist age.', 'Pinker urges us to overcome these cultural, psychological, political, and spiritual biases, and to take a more objective view of the world. But human beings are not objective creatures. When social scientists write about life expectancy, educational attainment, nutrition, crime, and the other issues Pinker addresses, they often use the abbreviation Q.O.L., for “quality of life.” They use S.W.B. to refer to “subjective well-being”—the more elusive phenomenon of happiness, fulfillment, or life satisfaction. In “Citizen Kane,” Orson Welles’s media tycoon enjoys high Q.O.L. and low S.W.B. He is healthy, wealthy, and unhappy. The question is whether what befalls individuals might also befall societies. If so, life could be getting much better objectively, on the social scale, without getting all that much better subjectively, on the individual scale.', '“Harold, you have to stop turning the divorce papers into rabbits. Just sign them and move on.”', 'The most obvious way to tackle this question is to survey people from different societies. The annual World Happiness Report combines data from Gallup opinion surveys with economic and sociological studies; it finds that, in general, citizens of high-Q.O.L. countries (Finland, Norway, Canada, Germany) report higher levels of S.W.B. than citizens of low-Q.O.L. countries (Venezuela, Chad, Laos, Iraq). Look closely, though, and the story is more nuanced. Although economics shapes S.W.B., so do social and political factors: despite immense economic growth, Chinese citizens are no happier today than they were in 1990 (fraying social ties, created by rural-to-urban migration, may be to blame), while in many Latin-American countries people report higher S.W.B. than their otherwise low Q.O.L. predicts. (Latin-American respondents often cite their strong family bonds as a special source of happiness.)', 'In the United States, the two measures have diverged. Although per-capita income has more than doubled since 1972, Americans’ S.W.B. has stagnated or even declined. In a contribution to the 2018 World Happiness Report, the economist Jeffrey Sachs attributes this divergence to a public-health crisis centered on obesity, drug abuse, and depression, and to a growing disillusionment with business and government. From all this data, the picture is one of large-scale predictability and small-scale volatility. Thanks to broad improvements in quality of life, today’s children are likelier to be happier than their grandparents were. But within any shorter span of time—a decade, a generation, an electoral cycle—there’s no guarantee that S.W.B. won’t decline even as Q.O.L. continues to rise.ADVERTISEMENT', 'These metrics may reflect something fundamental about how we experience life. Many psychologists now subscribe to the “set point” theory of happiness, according to which mood is, to some extent, homeostatic: at first, our new cars, houses, or jobs make us happy, but eventually we adapt to them, returning to our “set points” and ending up roughly as happy or unhappy as we were before. Researchers say that we run on “hedonic treadmills”—we chase new sources of happiness as the old ones expire—and that our set points are largely immovable and determined by disposition. Some fundamental changes can affect our happiness in a lasting way—getting married, immigrating to a wealthy country, developing a drug addiction—but many life improvements are impermanent in character. Although food quality may have been worse in 1967, the pleasure of today’s better meals is intrinsically fleeting. More people survive heart attacks than in the past, but the relief of surviving wears off as one returns to the daily grind.', 'The set-point theory is dispiriting, since it implies limits to how happy progress can make us, but it also suggests that progress is more widespread than we feel it to be. This last conclusion, though, makes sense only if we define “progress” in a certain way. “Imagine Seema, an illiterate woman in a poor country who is village-bound, has lost half her children to disease, and will die at fifty, as do most of the people she knows,” Pinker writes:', 'Now imagine Sally, an educated person in a rich country who has visited several cities and national parks, has seen her children grow up, and will live to eighty, but is stuck in the lower middle class. It’s conceivable that Sally, demoralized by the conspicuous wealth she will never attain, is not particularly happy, and she might even be unhappier than Seema, who is grateful for small mercies. Yet it would be mad to suppose that Sally is not better off.', 'Pinker is right: Sally is better off. To say so, however, is to acknowledge that we can be better off without feeling that way—working two jobs to pay tuition and save for retirement, Sally still suffers—or worse off without knowing it. Progress is objective and impersonal, at least in part, and can unfold without making us happier. “The goal of progress,” Pinker concludes, “cannot be to increase happiness indefinitely, in the hope that more and more people will become more and more euphoric.” Quality of life is higher today, no matter what you think, and it was lower under Communism, no matter how you feel about those whole-night concerts and epic soccer games. A blissful existence in the Matrix wouldn’t count as progress. There’s more to life than subjective well-being.', 'In a book titled “The Optimism Gap: The I’m OK–They’re Not Syndrome and the Myth of American Decline,” from 1998, the public-policy reporter David Whitman cited statistics showing that, in nearly every domain of life—crime, pollution, health, income, happiness—Americans were optimistic about themselves but pessimistic about society as a whole. While believing that crime was rising in general, they congratulated themselves for living in neighborhoods that were mostly crime-free; convinced that the economy was getting worse, they remained confident about their own earning potential. Pinker, too, finds that people are afraid for civilization but hopeful about themselves. Certain that those around them are living lives of quiet desperation, they continue to predict increases in their own life satisfaction. But it seems that this optimism gap isn’t just inaccurate; it’s pretty much backward. The world, as an objective whole, has been getting better. It’s our individual experiences of life that are unlikely to improve. We should be optimistic about civilization but neutral about our own future happiness.', 'A final reason for doubting progress is the future, in all its terrifying potentiality. One of Pinker’s most persistent critics is the statistician and risk analyst Nassim Nicholas Taleb, the author of “The Black Swan,” “Fooled by Randomness,” and other explorations of uncertainty. For the past few years, in a relentless barrage of tweets and Facebook posts, Taleb has responded to Pinker’s optimism by distinguishing between “thin-tailed” historical trends—picture the trailing ends of a bell curve—which are likely to continue indefinitely, and “fat-tailed” ones, which retain their capacity to surprise. Pinker shows that, during the past century, per-capita deaths from fire have declined by ninety per cent in the United States. In Taleb’s view, this is a thin-tailed trend, since it’s the result of innovations, such as better materials and building codes, that are unlikely to reverse themselves. By contrast, the decline in deaths from terrorism—far more people were killed by terrorists in the nineteen-sixties and seventies—is a fat-tailed trend; as Taleb writes on Facebook, “one biological event can decimate the population.” Pessimists of the Taleb school argue that we underestimate the number of fat-tailed trends. In a review of “Enlightenment Now,” the theoretical computer scientist Scott Aaronson imagines a hypothetical book, published in 1923, about “the astonishing improvements in the condition of Europe’s Jews.” The authors of such a book, Aaronson writes, would have reassured themselves that “an insane number of things would need to go wrong simultaneously” for that progress to be reversed—which, needless to say, is what happened.', 'Maybe our views about progress depend on our time horizons. Charles C. Mann’s “The Wizard and the Prophet: Two Remarkable Scientists and Their Dueling Visions to Shape Tomorrow’s World” tells the stories of two researchers, William Vogt and Norman Borlaug, who occupied opposing sides of the twentieth-century debate about the human population. In Mann’s terms, Vogt was a “prophet”: he predicted that, unless global population growth could be slowed, worldwide famine would result. Borlaug was a “wizard,” who argued that innovations in agriculture would make it possible for farmers to feed everyone. In the event, Borlaug was right: the “Green Revolution,” which he spearheaded, dramatically increased crop yields and saved billions of lives. But the deeper debate between the two sides—“Cut back or produce more?”—persists, this time around climate change. Today, pessimistic prophets argue that radical conservation is the only way to avoid a climatic apocalypse, while optimistic wizards propose innovating our way out of the crisis, perhaps through geoengineering or the creation of new energy sources. Our species seems to face a fork in the road: “If a government persuades its citizenry to spend huge sums revamping offices, stores, and homes with the high-tech insulation and low-water-use plumbing urged by Prophets,” Mann writes, “the same citizenry will resist ponying up for Wizards’ new-design nuclear plants and monster desalination facilities.”', 'Mann thinks the wizard–prophet distinction reflects a fundamental biological reality. If bacteria are left to grow in a petri dish, they’ll multiply quickly, then consume all their resources and die. The same goes for all species adaptive enough to flourish unconstrained. At first, “the world is their petri dish,” Mann writes. “Their populations grow at a terrific rate; they take over large areas, engulfing their environment. . . . Then they hit a barrier. They drown in their own wastes. They starve from lack of food.” A biologist tells Mann that “it is the fate of every successful species to wipe itself out.”', 'Both wizards and prophets hope that we can break this pattern. Wizards exhort us to “soar beyond natural constraints” using technology. (Think of Elon Musk, with his solar roof tiles and spaceships.) Prophets implore us to reach, through conservation and political reform, a “steady-state accommodation” with nature. (“What the climate needs to avoid collapse is a contraction in humanity’s use of resources,” the activist Naomi Klein writes.) Both sides agree that progress of a general sort isn’t enough: unless we adopt a decisive and coherent survival strategy, we’ll become victims of our own success. “The Wizard and the Prophet” provides an unsettling coda to “Enlightenment Now.” Pinker could be right in the short term but wrong in the long term. Maybe the world is getting better, but not better enough, or in the right ways.', 'In the Middle Ages, painters used triptychs to sum up the state of the world. On the left, one might see our origins, in the Garden of Eden; in the center, ordinary, terrestrial life; on the right, the torments of Hell. Above it all, Christ floats in Heaven, surrounded by angels: our redemptive future. One longs for a modern equivalent—a data-driven version of Fra Angelico’s “Last Judgment” or Hieronymus Bosch’s “Garden of Earthly Delights” equal to the contradictions of the human situation.', 'In “Factfulness: Ten Reasons We’re Wrong About the World—and Why Things Are Better Than You Think,” the Swedish global-health statistician Hans Rosling, who wrote the book with his son and daughter-in-law, tries to find such a picture. Most depictions of the world, Rosling thinks, are either too optimistic or too pessimistic; if they don’t succumb to despair, they seem to look too quickly away from suffering. Rosling adopts a mantra—“Bad and better”—to avoid these extremes. “Think of the world as a premature baby in an incubator,” he suggests:', 'The baby’s health status is extremely bad, and her breathing, heart rate, and other important signs are tracked constantly so that changes for better or worse can quickly be seen. After a week, she is getting a lot better. On all the main measures, she is improving, but she still has to stay in the incubator because her health is still critical. Does it make sense to say that the infant’s situation is improving? Yes. Absolutely. Does it make sense to say it is bad? Yes, absolutely. Does saying “things are improving” imply that everything is fine, and we should all relax and not worry? No, not at all. Is it helpful to have to choose between bad and improving? Definitely not. It’s both. It’s both bad and better. Better, and bad, at the same time. . . . That is how we must think about the current state of the world.', 'Rosling’s image captures many of the perplexities of our collective situation. We desperately want the baby to survive. We also know that survival doesn’t guarantee happiness. The baby is struggling, and suffering, and will continue to do so; as a result, we’re more likely to be happy for her than she is to be happy for herself. (Pinker, similarly, is happier for us than we are.) It’s possible, moreover, that she’ll be saved only temporarily. No one is ever truly out of the woods.', 'In the meantime, the baby’s survival depends on the act of diagnosis. Until her ailments are identified, they can’t be cured. Problems and progress are inextricable, and the history of improvement is also the history of problem-discovery. Diagnosis, of course, is an art in itself; it’s possible to misunderstand problems, or to overstate them, and, in doing so, to make them worse. But a world in which no one complained—in which we only celebrated how good we have it—would be a world that never improved. The spirit of progress is also the spirit of discontent.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/are-things-better-or-worse-than-theyre-being-portrayed/qotw0906/', '2020-09-10T12:00:00Z', '2020-09-10T12:00:00Z'),
  ('l6549', 'how-special-are-humans', 'b-janszen', 'name', null, array['Humans are unquestionably unique. Unique in a way and to a scale unprecedented in Earth’s history. The question is: Are ‘unique’ and ‘special’ the same and/or equivalent? In my opinion, yes, we are both unique and special. We are unique in a number of ways – opposable thumbs, large brains, use of fire, etc. These are all ‘special’ traits, too, but what I believe makes us truly special is the scale at which we affect the planet. We are special in that, unlike any other species in existence, we can eradicate entire species’ at unprecedented scales as well as develop technology and deepen spiritually at quantum levels.', 'We are currently at a crossroads of the species’ and earth’s history where we face potential mass extinction (of humans and innumerable species) on one hand and technological and psychological innovation that could catapult the species (and planet) into a new age on the other. In one dystopian future, the remnants of human civilization are as bleary as those of the dinosaurs. A species that evolved to be big, strong, and powerful enough to inhibit the evolution of fellow Earth inhabitants. A species that evolved beyond its means and eventually was corrected by the Earth’s intuitive homeostasis.', 'Overall, I believe that whatever our fate is at the end of the day, it is in the best interest of the Earth’s evolution as well as whatever lies beyond in the unknown Universe.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/how-special-are-humans-qotw/qotw0913-3/', '2020-09-13T12:00:00Z', '2020-09-13T12:00:00Z'),
  ('l6546', 'how-special-are-humans', 'scientific-american', 'name', null, array['HALLMARK TRAITS of the human body did not all arise anew in our species. Instead they emerged piecemeal in our forebears over millions of years. Many of these traits seem to have helped support two defining trends in our evolution: upright locomotion and tool use. See image below:']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/how-special-are-humans-qotw/qotw0913-2/', '2020-09-13T12:00:00Z', '2020-09-13T12:00:00Z'),
  ('l6541', 'how-special-are-humans', 'charles-q-c', 'name', null, array['Humans are unusual animals by any stretch of the imagination. Our special abilities, from big brains to opposable thumbs, have allowed us change our world dramatically and even leave the planet. There are also odd things about us that are, well, just special in relation to the rest of the animal kingdom. So what exactly makes us so special? Some things we take completely for granted might surprise you.', 'Speech', 'The larynx, or voice box, sits lower in the throat in humans than in chimps, one of several features that enable human speech. Human ancestors evolved a descended larynx roughly 350,000 years ago. We also possess a descended hyoid bone — this horseshoe-shaped bone below the tongue, unique in that it is not attached to any other bones in the body, allows us to articulate words when speaking.', 'Upright Posture', 'Humans are unique among the primates in how walking fully upright is our chief mode of locomotion. This frees our hands up for using tools. Unfortunately, the changes made in our pelvis for moving on two legs, in combination with babies with large brains, makes human childbirth unusually dangerous compared with the rest of the animal kingdom. A century ago, childbirth was a leading cause of death for women. The lumbar curve in the lower back, which helps us maintain our balance as we stand and walk, also leaves us vulnerable to lower back pain and strain.', 'Nakedness', 'We look naked compared to our hairier ape cousins. Surprisingly, however, a square inch of human skin on average possesses as much hair-producing follicles as other primates, or more — humans often just have thinner, shorter, lighter hairs. Fun fact about hair: Even though we don’t seem to have much, it apparently helps us detect parasites, according to one study.', 'Clothing', 'Humans may be called “naked apes,” but most of us wear clothing, a fact that makes us unique in the animal kingdom, save for the clothing we make for other animals. The development of clothing has even influenced the evolution of other species — the body louse, unlike all other kinds, clings to clothing, not hair.', 'Extraordinary Brains', 'Without a doubt, the human trait that sets us apart the most from the animal kingdom is our extraordinary brain. Humans don’t have the largest brains in the world — those belong to sperm whales. We don’t even have the largest brains relative to body size — many birds have brains that make up more than 8 percent of their body weight, compared to only 2.5 percent for humans. Yet the human brain, weighing only about 3 pounds when fully grown, give us the ability to reason and think on our feet beyond the capabilities of the rest of the animal kingdom, and provided the works of Mozart, Einstein and many other geniuses.', 'Hands', 'Contrary to popular misconceptions, humans are not the only animals to possess opposable thumbs — most primates do. (Unlike the rest of the great apes, we don’t have opposable big toes on our feet.) What makes humans unique is how we can bring our thumbs all the way across the hand to our ring and little fingers. We can also flex the ring and little fingers toward the base of our thumb. This gives humans a powerful grip and exceptional dexterity to hold and manipulate tools with.', 'Fire', 'The human ability to control fire would have brought a semblance of day to night, helping our ancestors to see in an otherwise dark world and keep nocturnal predators at bay. The warmth of the flames also helped people stay warm in cold weather, enabling us to live in cooler areas. And of course it gave us cooking, which some researchers suggest influenced human evolution — cooked foods are easier to chew and digest, perhaps contributing to human reductions in tooth and gut size.', 'Blushing', 'Humans are the only species known to blush, a behavior Darwin called “the most peculiar and the most human of all expressions.” It remains uncertain why people blush, involuntarily revealing our innermost emotions (we do know how it works). The most common idea is that blushing helps keep people honest, benefiting the group as a whole.', 'Long Childhoods', 'Humans must remain in the care of their parents for much longer than other living primates. The question then becomes why, when it might make more evolutionary sense to grow as fast as possible to have more offspring. The explanation may be our large brains, which presumably require a long time to grow and learn.', 'Life after Children', 'Most animals reproduce until they die, but in humans, females can survive long after ceasing reproduction. This might be due to the social bonds seen in humans — in extended families, grandparents can help ensure the success of their families long after they themselves can have children.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/how-special-are-humans-qotw/qotw0913/', '2020-09-13T12:00:00Z', '2020-09-13T12:00:00Z'),
  ('l6574', 'what-are-the-factors-that-divide-our-two-main-political-parties', 'nick-s', 'name', null, array['The very existence of a two-party system of government is designed to create duality, separation, and thus, opposition. Those truly in power have used the age-old, ever-successful method of pinning the public against each other in order to create a cloud of dust around the decisions truly being made and their effects on the public.', 'Imagine a potion being concocted by the wealthy corporate and political elites. There are a number of ingredients tactical to both maintain their power and build their wealth. It all revolves around domesticating and brainwashing the public into believing and acting against their own best interests, and done so under the guise of democracy and freedom. Here are some of those ingredients:', 'Fear. Both parties add a dollop of fear, though the Republican party is especially tactical in their usage. Right now, right wing media is filled with rhetoric around an ‘unrecognizable America’ if Biden wins the election, a scheme by Democrats to take our liberties away, etc. Generally unfounded on evidence, this fear-mongering rhetoric leads to irrational views and actions by the people in its wake.', 'Beyond just the media, fear is a natural reaction to change. Amidst one of the greatest eras of transformation in the world’s history, naturally a large percentage of the population has reacted with profound fear of the unknown. This is a natural reaction, yet a hurdle of being human that we are evolving through. Until our collective consciousness has evolved, this fear of the unknown will be easy pickings for those in power looking to manipulate large masses of the public.', 'Values. Certain ‘values’ have been politicized to such an extent that a single value alone can dictate one’s entire political affiliation. This is especially true within the Republican platform. Values such as gun rights, religious views (anti-abortion, alliance with Israel), anti-immigration hostility, distrust of government, amid many others, are often such strong views that they trump all else in regards to political affiliation. The more locked in to any one of these values, the more antagonistic the other side seems.', 'Dishonesty. The public is being fed news through a few select vessels of their choosing. Yet all news is filtered somehow, all news is funded somehow, and thus, all news is biased somehow. Each political parties play by their own ‘games’, relatively, however they share a common theme of sugarcoating reality to protect their image. Thus, like a wheat mill, the media is distorting reality, and we are being fed this processed version. We can only be so ‘woke’. Whether subtle distortion or blatant dishonesty (as the GOP has normalized), feeding the public a smorgasbord of distorted reality is guaranteed to stir up confusion and disdain.', 'These three ingredients are key in the potion of our political divide. They have, for centuries, been successful means for maintaining power and compounding wealth among the ‘sheep herders’, and today, a modern-day updated version of the same software is still being used to herd the sheep around. I believe we are en route to evolving through this model, however have a ways to go. Until then, we must continue to strive for truth, maintain presence, and call out injustice whenever and wherever possible.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/what-are-the-main-factors-that-divide-our-two-political-parties/qotw0920-4/', '2020-09-20T12:00:00Z', '2020-09-20T12:00:00Z'),
  ('l6571', 'what-are-the-factors-that-divide-our-two-main-political-parties', 'paul-w', 'name', null, array['When your party’s presidential candidate is trailing in the polls by nearly 10 pointswith a little over three months to go, it’s natural to start worrying about what will happen if he loses. And if you’re a Republican, there’s an entire cable network devoted to filling your evenings with terror.', 'Consider what Tucker Carlson, the highest-rated cable TV host of the moment, told his viewers Thursday night:The presidential election, in fact, believe it or not, is almost right here. In some places, early voting begins in just over a month. The results of that voting will define the country’s future. If Democrats take both the Senate and the White House, and they could, you will not recognize America a year from now.', 'This kind of message has particular resonance for conservatives, since by definition they’re inclined against change. And those who seek to mobilize them — such as Republican candidates or right-wing TV hosts — will almost inevitably wind up telling them that the change that will come will be not just unpleasant but downright cataclysmic. We hear this every four years, without fail.', 'It’s not that Democrats don’t predict disaster if they lose, because they do. But the conservative warnings of doom have a particular theme: the end of America as we know it.AD', 'I can’t count how many times in 2008 Republicans said that Barack Obama had a secret plan to remake the country into something utterly unrecognizable. And what did he do with the eight years he was in office? Exactly what any sane person would have predicted: He governed as a reasonably liberal Democrat, with some successes and some failures. By the time January 2017 rolled around, America could still be recognized.', 'Now make no mistake, having your party in the opposition is undoubtedly a drag. You have to open up the paper or turn on the TV every day to see that the president has begun some new initiative you disagree with, or appointed some high-ranking official you dislike. It’s frustrating.', 'But all of us, no matter our party, will have to endure multiple presidents from the other side over the course of our lifetimes. It’s the nature of democracy. And yes, that’s sometimes downright awful. But at least since 1865, the country has always remained intact.', 'But I suspect that fear of change is going to grow more intense on the right, not because Joe Biden is such a terrifying figure (I mean, c’mon), and not even because President Trump has taken conservatives to such a paradise that they can’t bear the thought of losing it.AD', 'No, it’s because Trump has failed.', 'I don’t mean the failures you may be thinking of, which are legion. I mean that as Trump supporters contemplate the unsettling prospect of future change, they can’t help but realize, even if unconsciously, that Trump hasn’t delivered on the most basic change he promised, which was to arrest and reverse the deep and fundamental social changes so many conservatives find so troubling.', 'That was the heart of “Make America Great Again”: the idea that we could revert to some point in the past, unwind the clock to when things were great. Keep in mind that for many conservatives, nearly all the social developments of the past few decades have ranged from objectionable to horrific. Kids don’t respect their elders, fewer people are going to church, women demand equality, gay people can get married, everyone’s talking about racism, and when you go down to your local supermarket, you hear people speaking a bunch of different languages.AD', 'And guess what: Donald Trump couldn’t do a thing about any of it.', 'He’s been president for four years, and no reversal of history has taken place. Young people are still driving you nuts, that rap music is everywhere you go, and you aren’t given the respect you think you deserve. This is the most anti-immigrant administration in a century, and yet the country is still full of immigrants.', 'It turned out that these are deep and fundamental changes, changes any one president can’t control.', 'Look at the campaign Trump is running, all about how chaos is overtaking the streets. Yes, it’s exactly what Fox News viewers have been warned about every night for years. But whatever you think is happening (even if your view is distorted and exaggerated), it’s happening while Trump is president, not because some permissive Democrat is letting the hooligans run wild. Surely even some of Trump’s supporters are aware of the irony.', 'In the end, that may be the most frightening thing for them: not that a Democratic president would bring distressing change to America but that the change will come no matter who is president. If America is going to become unrecognizable to conservatives, it won’t be because we pass universal health care or raise the minimum wage. It’ll be because time will continue to move forward.AD', 'That is what Trump promised them he could stop. But he never could. And soon they’ll be more upset about it than ever.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/what-are-the-main-factors-that-divide-our-two-political-parties/qotw0920-3/', '2020-09-20T12:00:00Z', '2020-09-20T12:00:00Z'),
  ('l6568', 'what-are-the-factors-that-divide-our-two-main-political-parties', 'pamela-p', 'name', null, array['Partisans on both sides of the aisle significantly overestimate the extent of extremism in the opposing party. The more partisan the thinker, the more distorted the other side appears. And when we see the opposition as extremists, we fear them. Our tribal thinking prepares us for battle.', 'More In Common (2019) Perception Gap StudySource: Image by Pamela Paresky', 'What’s the solution? More information? More political engagement? More education?', 'Surely more information leads to better judgment. But social scientists at the international initiative More in Common find that having more information from the news media is associated with a less accurate understanding of political opponents. Part of the problem appears to be the political biases of media sources themselves. Of all the various news media examined, only the traditional TV networks, ABC, NBC, and CBS, are associated with a better understanding of political views.', 'What about more political engagement and education? Here again, we’re out of luck. Those who are most accurate in their understanding of each side’s political views are the politically disengaged. They are three timesmore accurate than the most engaged and passionate partisans. Even education is handicapping — at least for those on the left. The accuracy of Republicans’ views of Democrats is not affected by higher education, but liberals with postgraduate degrees are the least accurate about their ideological opponents. They are also the most afflicted with “affective polarization,” hostile feelings toward people of the opposing political party.', 'This discrepancy may be a result of the lack of political diversity among professors and administrators on campus. As political scientist Sam Abramsfound, the average left to right ratio of professors nationwide is 6 to 1 and the ratio of student-facing administrators is 12 to 1. Democrats who have few or no Republican friends see the other side as more extreme than do those with more politically diverse friends. And the more educated Democrats are, the less likely they are to have friends who don’t share their political beliefs.', 'As a result, there aren’t many opportunities on campus for the left to gain a nuanced understanding of their ideological opponents. Nor is there much chance for students to watch professors model cross-partisan friendships or friendly disagreement. And many of those who hold unpopular political views are unwilling to reveal their thinking. Self-censoring and the associated misrepresentation of preferred views (what social scientists call “preference falsification”) both lead to and result from what is known as “pluralistic ignorance.” This is the incorrect assumption on the part of many members of a community that the majority subscribe to an orthodox view.', 'All of this suggests that the way to close the perception gap is to expose people to a more intellectually diverse group of people and set of views, and turn down the tribalism.', 'Newspaper op-ed pages can make a difference by hiring — and fiercely protecting — opinion columnists whose views don’t square with those of the majority of their readers. Think tanks, which often follow a certain ideological bent, can hire scholars who are willing to amicably challenge the conclusions of their colleagues.', 'And nowhere is the need for intellectual diversity more urgent than in higher education — the very institutions that were once supposed to protect unpopular thinkers and expose students to uncomfortable ideas. But thanks to the emergence of what is now called “cancel culture,” students, faculty, and visiting speakers are targeted for opposing prevailing campus orthodoxy.', 'Consider some well-known examples of contrarians and gadflies from the past few years: Ronald Sullivan, the Harvard law professor, whose position as dean of an undergraduate residential college was terminated because students complained that his legal representation of Harvey Weinstein made them “feel unsafe”; Allison Stanger, the political scientist at Middlebury who was physically assaulted by students for her discussion with libertarian scholar Charles Murray; Bret Weinstein, the Evergreen State College biologist who was hounded from his position for opposing a “day of absence” when only people of color were welcome on campus; Lucia Martinez Valdivia, the self-identified mixed-race and queer professor at Reed College accused by students of being a “race traitor,” “anti-black,” and “ableist” because she spoke about questioning feelings of oppression; and Joshua Clover, the UC Davis professor whose manifestly uncivil anti-law-enforcement comments were met not with arguments for the value of civil and productive disagreement and against his preferred ad hominem tactics, but with a rally and petition to have him fired.', 'What these and similar cases have in common isn’t the political leanings of the ostracized faculty members (though many of them are, to one degree or another, politically liberal). It is the apparent inability of their accusers to accept that other points of view should be entertained and discussed on campus, much less accepted as valid perspectives.', 'That inability is a function of an ideological monoculture in which any view that runs contrary to the prevailing moral code is seen as making people “unsafe;” that the mere presence on campus of people who hold “problematic” views is “harmful;” that words are violence.', 'An understanding of the value of sharp yet productive civil disagreement with ideological opponents is largely absent. One recent study even found that 15% of Republicans and 20% of Democrats thought the country would be better off if large numbers of opposing partisans “just died.”', 'Liberal democracy is built on a philosophy of freedom of expression combined with a set of social norms that allow the articulation of unpopular opinions without fear of retribution. It relies on an ability to acknowledge the humanity of those whose views we don’t like and a commitment to defend their right to speak. Embodying these principles today is too rare and requires too much courage.', 'So what can you do?', 'Consume news from sources that don’t merely confirm your views. Insist that your preferred news media platforms provide an intellectually diverse slate of writers — and that they fiercely protect them when the mob comes. Ask your university to commit to the Foundation for Individual Rights in Education’s 5 ways university presidents can prove their commitment to free speech. Resist the temptation to join in the outrage on social media. And make sure you have friends who don’t share your views.', 'Whether on a college campus or in the wider world, find what C.S. Lewis called “second friends.” A second friend is someone you like and respect who disagrees with you. “He has read all the right books but has got the wrong thing out of every one,” explained Lewis. “It is as if he spoke your language but mispronounced it.” Cherish these friends. And listen to them.', 'We have lost touch with a fundamental premise of a functioning democracy: Our ideological opponents are not our enemies. It is not even a matter of “tolerating” those who disagree. Dissent and disagreement are necessary in order to sharpen our thinking and come to better conclusions. We need each other in order to do the essential work of creating a more perfect union. The good news is that we have more in common than we think.', 'But if we keep doing what we’re doing, we’ll continue hating each other too much to see it.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/what-are-the-main-factors-that-divide-our-two-political-parties/qotw0920-2/', '2020-09-20T12:00:00Z', '2020-09-20T12:00:00Z'),
  ('l6597', 'how-is-the-intensity-of-these-times-affecting-people', 'nick-s', 'name', null, array['The onslaught of dark, disappointing, and potentially traumatic information that is emerging and circulating on a daily basis is, not surprisingly, having an affect on the human psyche. Many folks I have spoken with have described experiencing a certain un-traceable darkness and confusion in their consciousness. I believe that on a series of subtle levels, the collective consciousness is in a very fragile, sensitive place right now. Whether we realize it or not, I think it is quite clear that the trauma of a pandemic, un-resolved racial and social injustice, a worsening climate issue, and incompetent leadership would be some of the main ingredients in this emotional and psychological unrest.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/how-is-the-intensity-of-these-times-affecting-people/how-is-the-intensity-of-these-times-affecting-people/', '2020-09-30T12:00:00Z', '2020-09-30T12:00:00Z'),
  ('l6594', 'how-is-the-intensity-of-these-times-affecting-people', 'cory-s', 'name', null, array['The Covid-19 pandemic has been going on in the United States for months, and yet many questions still remain. The biggest one for many Americans is: When will life go back to normal? And, what will that new normal even look like?', 'As summer approaches, you may find yourself longing for events that you would typically look forward to, such as vacations, holidays or time spent with your family.', 'On social media, people who are currently sheltering in place expressed that it’s challenging to not have anything to look forward to or anticipate.', 'Without these usual benchmarks, you might feel off or sad. “Uncertainty doesn’t sit well,” Kevin Antshel, clinical psychologist and director of the clinical psychology program at Syracuse University tells CNBC Make It.', 'Here’s how to cope with not knowing what’s coming next.', 'Why humans hate the unknown', '“The fear of the unknown is possibly the most fundamental fear of human beings,” Antshel says.', 'From an evolutionary perspective, humans have been able to survive because we’re able to plan. We’re socialized from childhood to believe that “there’s a predictable universe” and order in which things should happen, Antshel says.', '“Extraordinarily high levels of uncertainty are really against how we’ve advanced as human beings,” he says. For example, under normal circumstances, you’d be able to assemble the resources necessary to achieve a plan, and then go implement it.', '“When things don’t make sense, or they run counter to what it typically is, then we experience these high levels of negative feelings,” Antshel says.', 'What uncertainty feels like', 'We’re hand-wired to avoid uncertainty, because it makes us feel lots of negative emotions, Antshel says. The “vast majority” of people are experiencing some level of emotional distress or unpleasant emotions during this time, he says.', 'These feelings all come back to uncertainty. “Fear and anxiety really run hand-in-hand: The more things are uncertain, the more we’re going to fear, and the more we fear things, the more we are anxious,” he says. While planning for post-pandemic life can feel comforting, thinking too much about the future can also increase our anxious thoughts.', 'The more prolonged anxiety is, the more likely it is to manifest itself as depression, which is characterized by a loss of interest in things, hopelessness and helplessness, he says. It can feel like this difficult period will be going on forever, with no end in sight.', 'On top of this, you might find that you’re mourning the loss of events that you were anticipating, such as weddings, big work projects or graduation.', 'How to get comfortable with unpredictability', 'It’s important to think about “how we frame things to ourselves internally,” Antshel says.', 'Another helpful coping mechanism is to “engage in things that are goal-oriented, but are not necessarily goal-directed for the future,” Antshel says. Projects or hobbies (such as baking bead or doing a puzzle) that can give you a sense of accomplishment and allow you to have a certain outcome of certainty can be soothing.', 'And finally, it can be reassuring to understand that your feelings are very normative. “People who had never considered themselves to be anxious or depressed or now reporting these symptoms,” he says.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/how-is-the-intensity-of-these-times-affecting-people/qotw0927-2/', '2020-09-30T12:00:00Z', '2020-09-30T12:00:00Z'),
  ('l6591', 'how-is-the-intensity-of-these-times-affecting-people', 'elke-vh', 'name', null, array['• With some 2.6 billion people around the world in some kind of lockdown, we are conducting arguably the largest psychological experiment ever;', '• This will result in a secondary epidemic of burnouts and stress-related absenteeism in the latter half of 2020;', '• Taking action now can mitigate the toxic effects of COVID-19 lockdowns.', 'In the mid-1990s, France was one of the first countries in the world to adopt a revolutionary approach for the aftermath of terrorist attacks and disasters. In addition to a medical field hospital or triage post, the French crisis response includes setting up a psychological field unit, a Cellule d’Urgence Médico-Psychologique or CUMPS.', 'Have you read?', 'In that second triage post, victims and witnesses who were not physically harmed receive psychological help and are checked for signs of needing further post-traumatic treatment. In those situations, the World Health Organization recommends protocols like R-TEP (Recent Traumatic Episode Protocol) and G-TEP (Group Traumatic Episode Protocol).', 'Since France led the way more than 20 years ago, international playbooks for disaster response increasingly call for this two-tent approach: one for the wounded and one to treat the invisible, psychological wounds of trauma.', 'In treating the COVID-19 pandemic, the world is scrambling to build enough tents to treat those infected with a deadly, highly contagious virus. In New York, we see literal field hospitals in the middle of Central Park.', 'But we’re not setting up the second tent for psychological help and we will pay the price within three to six months after the end of this unprecedented lockdown, at a time when we will need all able bodies to help the world economy recover.', 'The mental toll of quarantine and lockdown', 'Currently, an estimated 2.6 billion people – one-third of the world’s population – is living under some kind of lockdown or quarantine. This is arguably the largest psychological experiment ever conducted.', 'Estimated size of lockdowns around the worldImage: Statista', 'Unfortunately, we already have a good idea of its results. In late February 2020, right before European countries mandated various forms of lockdowns, The Lancet published a review of 24 studies documenting the psychological impact of quarantine (the “restriction of movement of people who have potentially been exposed to a contagious disease”). The findings offer a glimpse of what is brewing in hundreds of millions of households around the world.', 'In short, and perhaps unsurprisingly, people who are quarantined are very likely to develop a wide range of symptoms of psychological stress and disorder, including low mood, insomnia, stress, anxiety, anger, irritability, emotional exhaustion, depression and post-traumatic stress symptoms. Low mood and irritability specifically stand out as being very common, the study notes.', 'In China, these expected mental health effects are already being reported in the first research papers about the lockdown.', 'In cases where parents were quarantined with children, the mental health toll became even steeper. In one study, no less than 28% of quarantined parents warranted a diagnosis of “trauma-related mental health disorder”.', 'Among quarantined hospital staff, almost 10% reported “high depressive symptoms” up to three years after being quarantined. Another study reporting on the long-term effects of SARS quarantine among healthcare workers found a long-term risk for alcohol abuse, self-medication and long-lasting “avoidance” behaviour. This means that years after being quarantined, some hospital workers still avoid being in close contact with patients by simply not showing up for work.', 'Reasons for stress abound in lockdown: there is risk of infection, fear of becoming sick or of losing loved ones, as well as the prospect of financial hardship. All these, and many more, are present in this current pandemic.', 'The second epidemic and setting up the second tent online', 'We can already see a sharp increase in absenteeism in countries in lockdown. People are afraid to catch COVID-19 on the work floor and avoid work. We will see a second wave of this in three to six months. Just when we need all able bodies to repair the economy, we can expect a sharp spike in absenteeism and burnout.', 'We know this from many examples, ranging from absenteeism in military units after deployment in risk areas, companies that were close to Ground Zero in 9/11 and medical professionals in regions with outbreaks of Ebola, SARS and MERS.', 'Right before the lockdown, we conducted a benchmark survey among a representative sample of the Belgian population. In that survey, we saw that 32% of the population could be classified as highly resilient (“green”). Only 15% of the population indicated toxic levels of stress (“red”).', 'How stress under lockdown is affecting Belgians', 'In our most recent survey after two weeks of lockdown, the green portion has shrunk to 25% of the population. The “red” part of the population has increased by 10 percentage points to fully 25% of the population.', 'These are the people at high risk for long-term absenteeism from work due to illness and burnout. Even if they stay at work, research from Eurofound reports a loss of productivity of 35% for these workers.', 'In general, we know at-risk groups for long-term mental health issues will be the healthcare workers who are on the frontline, young people under 30 and children, the elderly and those in precarious situations, for example, owing to mental illness, disability and poverty.', 'All this should surprise no one; insights on the long-term damage of disasters have been accepted in the field of trauma psychology for decades.', 'The phases of disaster responseImage: When disaster strikes, Beverly Raphael, 1986', 'But while the insights are not new, the sheer scale of these lockdowns is. This time, ground zero is not a quarantined village or town or region; a third of the global population is dealing with these intense stressors. We need to act now to mitigate the toxic effects of this lockdown.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/how-is-the-intensity-of-these-times-affecting-people/qotw0927-1/', '2020-09-30T12:00:00Z', '2020-09-30T12:00:00Z'),
  ('l6611', 'what-were-you-doing-while-the-usa-slid-into-a-dictatorship', 'big-dave', 'name', null, array['After COVID, social unrest, and four years of the president’s shenanigans, I have now developed a good bit of cognitive dissonance. It has hard for me to take anything at face value, to find unbiased sources, and to have faith in our society anymore. Most of the information that orbits around my echo chamber has been shared so many times, I have lost touch with its true implications. Thus, I sit here, piecing the puzzle together of the president’s takeover of our democracy, yet completely numb to the reality of such fate.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/what-were-you-doing-while-the-usa-slid-into-a-dictatorship/what-were-you-doing-while-the-usa-slid-into-a-dictatorship-2/', '2020-10-13T12:00:00Z', '2020-10-13T12:00:00Z'),
  ('l6609', 'what-were-you-doing-while-the-usa-slid-into-a-dictatorship', 'b-janszen', 'name', null, array['Watching in amazement, yet stuck in debilitating fear. Even as the seemingly inconceivable began to unravel as reality in front of us, I sat stunned, glued to the screen, completely disconnected from the reality of what was happening. It is easy to dismiss tragic events in history as a collection of human ignorance, but when it is happening in real time, the vantage point changes. I certainly did not give enough attention to the warning sirens blaring from certain folks. While it is still not guaranteed that we will slide fully into a dictatorship, those seeds have been sewn and the evidence is there that such a fate is still very much a possibility. Now as much as ever. Accomplished via a simple, step-by-step recipe.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/what-were-you-doing-while-the-usa-slid-into-a-dictatorship/what-were-you-doing-while-the-usa-slid-into-a-dictatorship/', '2020-10-13T12:00:00Z', '2020-10-13T12:00:00Z'),
  ('l6645', 'what-will-trump-do-if-he-loses-the-election', 'nick-s', 'name', null, array['Imagine Trump’s power as a graph. He has been rollercoaster-ing for 50 years, yet steadily growing his power. He has now reached a point where his power has spiked to, by far, its highest point in his life. What would he do if he is all of a sudden de-throned and his power plunges? For a mentally unstable human as Trump is, this will be catastrophic. The mere thought of it has already worked its way through him, and he is talking about leaving the country or not knowing what he would do… he is clearly very flustered by the reality of being out of power (and add to that the potential for prison time).', 'With his last few months in office, he will fight to the literal death to keep his power (as power-mongerers always do). This mental illness is a lifestyle, and throughout history has played itself out over and over again – from ancient emperors to Hitler to modern billionaires like Jeff Bezos. Trump cannot conceive of returning to a reality in which he does not have extreme power, and thus, he will take on the mentality of fighting for his life. With his finger on the trigger of nuclear weaponry, he will bluff every bit of perceived power to intimidate the other side to leave him alone. He simply has nothing to lose at that point.', 'Ultimately, he will be killed – either by himself or someone else – within the next year. It will be the end of a mini civil war, and the beginning of an even more tense spell in the USA.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/what-will-trump-do-if-he-loses-the-election/qotw1018-2/', '2020-10-21T12:00:00Z', '2020-10-21T12:00:00Z')
on conflict (id) do nothing;
